    const HISTORICAL_25_RECOVERY_SCOPE_OFFSET: usize = HISTORICAL_25_RECOVERY_CONTRACT_OFFSET + 32;
    const HISTORICAL_25_RECOVERY_PREDECESSOR_BASIS_OFFSET: usize =
        HISTORICAL_25_RECOVERY_SCOPE_OFFSET + 32;
