    #[cfg(test)]
    std::thread_local! {
        static HISTORICAL_25_TEST_CRASH_AFTER_INSTALLED_STAGING: std::cell::Cell<bool> =
            const { std::cell::Cell::new(false) };
    }

    #[cfg(test)]
    fn historical_25_test_crash_after_installed_staging() {
        if HISTORICAL_25_TEST_CRASH_AFTER_INSTALLED_STAGING.with(|armed| armed.replace(false)) {
            panic!("test crash after durable Installed staging proof");
        }
    }

    const TC_HANDLE: TcHandle = TcHandle::new(0, 1);
    const RECONCILER_CONTROL_DIRECTORY: &str = "GTPU_RECONCILER_LOCKS";
    const RECONCILER_OPERATION_LOCK_SUFFIX: &str = "-operation-v1";
    const BPF_FS_MAGIC: u64 = 0xcafe_4a11;
    const CAP_NET_ADMIN: u32 = 12;
    const CAP_SYS_ADMIN: u32 = 21;
    const CAP_BPF: u32 = 39;

    /// A control directory starts at link count two and gains exactly one
    /// directory link per immutable authority/terminal marker.  The inventory
    /// permits no other children, so this is also an inexpensive structural
    /// replacement check after marker enumeration.
    pub(super) const fn control_marker_link_count_is_exact(nlink: u64, markers: usize) -> bool {
        nlink == 2 + markers as u64
    }

    pub(super) const fn empty_marker_link_count_is_exact(nlink: u64) -> bool {
        nlink == 2
    }

    /// Selector authority directories are private `0700` directories.  Mask
    /// the special permission bits too: a sticky, setgid, or setuid directory
    /// is not the immutable control object this protocol authorizes.
    pub(super) const fn selector_control_directory_mode_is_exact(mode: u32) -> bool {
        mode & 0o7777 == 0o700
    }

    /// `e7db129d` created the shared reconciler root with `create_dir`, so its
    /// mode was the process umask result, not a shipped `0755` ABI.  The
    /// compatibility route accepts only an ordinary owner-searchable directory
    /// with no special bits.  It never changes that shared mode: a per-current-
    /// leaf receipt is required before current ownership may use this route.
    pub(super) const fn historical_25_control_root_mode_is_compatible(mode: u32) -> bool {
        mode & 0o7000 == 0 && mode & 0o700 == 0o700 && mode & 0o022 == 0
    }

    pub(super) const fn current_recovery_authority_root_mode_is_observable(
        predecessor_handoff: bool,
        control_root_mode: u32,
    ) -> bool {
        if predecessor_handoff {
            historical_25_control_root_mode_is_compatible(control_root_mode)
        } else {
            selector_control_directory_mode_is_exact(control_root_mode)
        }
    }

    pub(super) const fn historical_25_owned_leaf_is_compatible(
        uid: u32,
        gid: u32,
        expected_uid: u32,
        expected_gid: u32,
        mode: u32,
        nlink: u64,
    ) -> bool {
        uid == expected_uid
            && gid == expected_gid
            && nlink == 2
            && historical_25_control_root_mode_is_compatible(mode)
    }

    /// A BPF object pin created by the shipped runtime is a single-link,
    /// owner-only regular bpffs inode. The kernel applies the caller umask to
    /// `0600`; the shipped process umask preserved both owner bits, so any
    /// widened, narrowed, re-owned, linked, or non-regular leaf is foreign or
    /// indeterminate authority rather than compatible residue.
    pub(super) const fn historical_25_pin_leaf_is_exact(
        is_regular: bool,
        uid: u32,
        gid: u32,
        expected_uid: u32,
        expected_gid: u32,
        mode: u32,
        nlink: u64,
    ) -> bool {
        is_regular
            && uid == expected_uid
            && gid == expected_gid
            && mode & 0o7777 == 0o600
            && nlink == 1
    }

    /// Compare a descriptor identity to the identity captured from the trusted
    /// path.  This is shared by root, control, and immutable-marker checks.
    pub(super) const fn selector_control_identity_is_exact(
        observed_device: u64,
        observed_inode: u64,
        expected_identity: Option<(u64, u64)>,
    ) -> bool {
        match expected_identity {
            Some((expected_device, expected_inode)) => {
                observed_device == expected_device && observed_inode == expected_inode
            }
            None => true,
        }
    }

    /// `syncfs` is the durability receipt for a newly created marker.  An
    /// unsupported sync is indistinguishable from an undurable namespace, so
    /// no error code (including `EINVAL`) is accepted as success.
    pub(super) const fn selector_control_syncfs_succeeded(result: bool) -> bool {
        result
    }

    /// A brand-new grouped graph is initially active: its hooks are live
    /// before management can publish the selector marker.  This separate,
    /// one-shot proof permits that legitimate initial sequencing while never
    /// treating an arbitrary empty active graph as a recovery candidate.
    pub(super) const fn selector_namespace_fresh_provisioning_is_exact(
        fresh_provenance: bool,
        cleanup_only: bool,
        hooks_attached: bool,
        datapath_current: bool,
        authority_maps_empty: bool,
    ) -> bool {
        fresh_provenance
            && !cleanup_only
            && hooks_attached
            && datapath_current
            && authority_maps_empty
    }

    /// An already-present initializing marker is recoverable only after a
    /// stopped, cleanup-only graph has been proved empty.  In particular,
    /// active fresh attachment is intentionally not recovery evidence.
    pub(super) const fn selector_namespace_initializing_recovery_is_exact(
        cleanup_only: bool,
        hooks_attached: bool,
        cleanup_datapath_safe: bool,
        authority_maps_empty: bool,
    ) -> bool {
        cleanup_only && !hooks_attached && cleanup_datapath_safe && authority_maps_empty
    }

    fn next_traffic_observation_gate(current: u64) -> Option<(u64, u64)> {
        let disabled = current.checked_add(if current & 1 == 0 { 2 } else { 1 })?;
        let enabled = disabled.checked_add(1)?;
        Some((disabled, enabled))
    }

    #[derive(Debug, Default)]
    pub(super) struct AyaGtpuRuntime {
        // Effect guards retain this registry while they hold the canonical
        // bounded operation flock. Sharing the registry with the guard lets
        // final readback compare the exact loaded graph, rather than only its
        // selector marker path.
        devices: Arc<Mutex<HashMap<u32, LoadedDevice>>>,
    }

    struct ReconcilerOwnership {
        // Preserve the original process-lifetime writer lease on the
        // namespace control directory. Older SDK writers lock this same inode,
        // so retaining it also keeps rolling upgrades split-brain safe.
        _lease: File,
        // Each protected operation re-opens this configured root and compares
        // it with the identity captured below.  Keeping an old descriptor
        // alive is not authority after an unmount or pathname replacement.
        bpffs_root_path: PathBuf,
        bpffs_root_device: u64,
        bpffs_root_inode: u64,
        control_root_name: &'static str,
        control_root_device: u64,
        control_root_inode: u64,
        control_dir_name: String,
        control_dir_device: u64,
        control_dir_inode: u64,
        control_dir_created: bool,
        operation_lock_name: String,
        operation_lock_device: u64,
        operation_lock_inode: u64,
        operation_lock_created: bool,
        // A predecessor root created by `e7db129d` can be shared and have an
        // ordinary umask-derived mode.  In that case normal ownership is
        // authorized only by the exact immutable hand-off marker in this
        // namespace's private leaf; its operation flock is that marker, not a
        // new object in the shared root.
        historical_25_handoff: Option<Historical25RootHandoff>,
        canonical_pin_dir: PathBuf,
        namespace_hash: [u8; 32],
    }

    #[derive(Debug, Clone)]
    struct Historical25RootHandoff {
        marker_device: u64,
        marker_inode: u64,
        legacy_control_dir_name: String,
        receipt: Historical25CurrentReceipt,
    }

    impl Historical25RootHandoff {
        /// Domain-separated commitment to the complete retained R5 source
        /// receipt and the exact authority objects from which it was read.
        /// The commitment is stored in the current WAL; no path, map ID, or
        /// object identity is exposed through the public receipt surface.
        fn terminal_receipt_commitment(&self, namespace_hash: [u8; 32]) -> Option<[u8; 32]> {
            let record = self.receipt.proof.record;
            if !record.is_terminal()
                || record.namespace_hash != namespace_hash
                || record.proof_map_id == 0
                || self.receipt.proof.map_id != record.proof_map_id
                || self.receipt.directory_device == 0
                || self.receipt.directory_inode == 0
                || record.current_control_device != self.receipt.directory_device
                || record.current_control_inode != self.receipt.directory_inode
                || self.marker_device == 0
                || self.marker_inode == 0
                || self.legacy_control_dir_name.is_empty()
            {
                return None;
            }
            let mut digest = Sha256::new();
            digest.update(b"opc.gtpu.current-ebpf-historical-r5-source-receipt\0r1");
            digest.update(crate::HISTORICAL_EBPF_GRAPH_RECOVERY_RECORD_CODEC_ID.as_bytes());
            digest.update(crate::HISTORICAL_EBPF_GRAPH_RECOVERY_KAT_ID.as_bytes());
            digest.update(HISTORICAL_25_RECOVERY_PROOF_MAP.as_bytes());
            digest.update(HISTORICAL_25_ROOT_HANDOFF_MARKER.as_bytes());
            digest.update(HISTORICAL_25_OPERATION_LOCK_MARKER.as_bytes());
            digest.update(b"\0legacy-authority-leaf\0");
            digest.update(self.legacy_control_dir_name.as_bytes());
            digest.update(b"\0handoff-directory-identity\0");
            digest.update(self.receipt.directory_device.to_be_bytes());
            digest.update(self.receipt.directory_inode.to_be_bytes());
            digest.update(b"\0operation-marker-identity\0");
            digest.update(self.marker_device.to_be_bytes());
            digest.update(self.marker_inode.to_be_bytes());
            digest.update(b"\0proof-map-identity\0");
            digest.update(self.receipt.proof.map_id.to_be_bytes());
            digest.update(b"\0canonical-r5-record\0");
            digest.update(record.encode());
            Some(digest.finalize().into())
        }
    }

    /// The predecessor's authority leaf. Its intentionally narrower
    /// validation mirrors the exact construction in `e7db129d`: that release
    /// used a SHA-256 leaf-name beneath `GTPU_RECONCILER_LOCKS` and flocked the
    /// directory itself, before the root-bound commitment and private-0700
    /// controls existed. We accept only that one legacy shape and retain its
    /// descriptor until retirement.
    struct Historical25LegacyOwnership {
        _lease: File,
        bpffs_root_path: PathBuf,
        bpffs_root_device: u64,
        bpffs_root_inode: u64,
        control_root_device: u64,
        control_root_inode: u64,
        control_dir_name: String,
        control_dir_device: u64,
        control_dir_inode: u64,
    }

    /// The current, root-bound namespace lease taken while a predecessor
    /// leaf-hash lease is still present.  It deliberately binds the current
    /// namespace digest to the *same* historical control-root inode.  The
    /// old release created that root without the current private-directory
    /// mode contract.  The terminal compatibility hand-off never changes that
    /// shared root: it publishes an immutable receipt in this exact private
    /// leaf while both leases are held, then retires only the matching legacy
    /// child.
    ///
    /// The leaf itself is a current-format, private `0700` authority inode;
    /// it is never removed by this operation.  This lets the normal current
    /// runtime retain the root-bound authority after the exact legacy child is
    /// retired, without changing another namespace under the shared root.
    struct Historical25CurrentOwnership {
        _lease: File,
        control_dir_name: String,
        control_dir_device: u64,
        control_dir_inode: u64,
        namespace_hash: [u8; 32],
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    struct Historical25CurrentReceipt {
        directory_device: u64,
        directory_inode: u64,
        proof: Historical25RecoveryProof,
    }

    #[derive(Debug, Clone, PartialEq, Eq)]
    struct Historical25QualifiedGraph {
        graph_device: u64,
        graph_inode: u64,
        identity: Historical25DatapathIdentity,
    }

    struct OperationControlLock {
        // Marker inventory remains rooted at the lifetime-lease directory.
        descriptor: File,
        // Bounded RFC 016 effects use a distinct persistent inode so a writer
        // that holds the lifetime lease can still take and release operations.
        lock_descriptor: File,
        operation: &'static str,
        locked: bool,
    }

    /// Production implementation of the opaque runtime effect guard.  The
    /// flock is intentionally released only when this value is dropped after
    /// the synchronous grouped map operation has completed.
    struct AyaSelectorNamespaceEffectGuard {
        ownership: Arc<ReconcilerOwnership>,
        lock: OperationControlLock,
        marker_expectation: GraphEffectMarkerExpectation,
        devices: Arc<Mutex<HashMap<u32, LoadedDevice>>>,
        ifindex: u32,
        graph: SelectorNamespaceGraphIdentity,
    }

    /// A graph receipt may additionally assert selector-marker semantics, but
    /// ordinary datapath transactions only need the exact structural graph.
    /// Keeping that distinction in the affine receipt prevents a legacy/TFT
    /// caller from taking a second flock merely to discover marker state.
    enum GraphEffectMarkerExpectation {
        Any,
        Bound(crate::selector_namespace::GtpuSessionSelectorBackendBinding),
        Unbound,
    }

    impl OperationControlLock {
        fn release(mut self) -> Result<(), GtpuError> {
            if self.locked {
                rustix::fs::flock(&self.lock_descriptor, rustix::fs::FlockOperation::Unlock)
                    .map_err(|error| GtpuError::io(self.operation, error.into()))?;
                self.locked = false;
            }
            Ok(())
        }
    }

    impl SelectorNamespaceEffectGuard for AyaSelectorNamespaceEffectGuard {
        fn finish(self: Box<Self>) -> Result<(), GtpuError> {
            let Self {
                ownership,
                lock,
                marker_expectation,
                devices,
                ifindex,
                graph,
            } = *self;
            let result = (|| {
                let current = AyaGtpuRuntime::revalidate_current_control_path(
                    &ownership,
                    &lock,
                    "ebpf_selector_effect_finish",
                )?;
                let devices = devices
                    .lock()
                    .map_err(|_| state_indeterminate("ebpf_selector_effect_finish"))?;
                let device = devices
                    .get(&ifindex)
                    .ok_or_else(|| state_indeterminate("ebpf_selector_effect_finish"))?;
                (AyaGtpuRuntime::selector_namespace_graph_identity(
                    ifindex,
                    device,
                    &ownership,
                    &current,
                    "ebpf_selector_effect_finish",
                )? == graph)
                    .then_some(())
                    .ok_or_else(|| state_indeterminate("ebpf_selector_effect_finish"))?;
                let (authority, terminal) = AyaGtpuRuntime::marker_inventory(&current)?;
                match marker_expectation {
                    GraphEffectMarkerExpectation::Any => Ok(()),
                    GraphEffectMarkerExpectation::Bound(binding) => {
                        let expected =
                            AyaGtpuRuntime::selector_binding_marker_name(&ownership, binding);
                        (authority.as_slice() == [expected] && terminal.is_empty())
                            .then_some(())
                            .ok_or_else(|| state_indeterminate("ebpf_selector_effect_finish"))
                    }
                    GraphEffectMarkerExpectation::Unbound => (authority.is_empty()
                        && terminal.is_empty())
                    .then_some(())
                    .ok_or_else(|| state_indeterminate("ebpf_selector_effect_finish")),
                }
            })();
            let released = lock.release();
            match (result, released) {
                (Ok(()), Ok(())) => Ok(()),
                (Err(error), Ok(())) | (_, Err(error)) => Err(error),
            }
        }
    }

    impl std::ops::Deref for OperationControlLock {
        type Target = File;

        fn deref(&self) -> &Self::Target {
            &self.descriptor
        }
    }

    impl Drop for OperationControlLock {
        fn drop(&mut self) {
            if self.locked {
                let _ =
                    rustix::fs::flock(&self.lock_descriptor, rustix::fs::FlockOperation::Unlock);
            }
        }
    }

    impl std::fmt::Debug for ReconcilerOwnership {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter
                .debug_struct("ReconcilerOwnership")
                .field("held", &true)
                .finish_non_exhaustive()
        }
    }

    struct LoadedDevice {
        // Keep the name used to resolve this exact ifindex.  A reused ifindex
        // is not the same managed interface, even when it hosts a graph with
        // structurally identical maps and programs.
        interface: String,
        ebpf: Ebpf,
        marked_owner_by_teid: HashMap<[u8; 4], [u8; UPLINK_MARK_KEY_LEN]>,
        default_teid_by_ue: HashMap<[u8; 4], [u8; 4]>,
        // Netlink tc links delete by interface/priority/handle rather than by
        // program ID. Keep both Aya/name-created and cleanup/index-created
        // links inert on drop, and detach them only after proving that both
        // live slots still contain our exact program IDs.
        //
        // `None` while the device is held cleanup-only: the maps and the
        // namespace lease are loaded, but no forwarding hook is attached.
        links: Option<DatapathLinks>,
        pin_dir: std::path::PathBuf,
        tc_priority: u16,
        datapath_identity: DatapathIdentity,
        // True while the device is held cleanup-only: forwarding is fenced and
        // only exact readback/removal are authorized. Activation clears this.
        cleanup_only: bool,
        // True only across terminal-successor finalization. Ordinary runtime
        // map/control entry points fail closed while the predecessor WAL may
        // still be authoritative; the finalizer clears it only after exact
        // post-retirement graph readback.
        successor_pending: bool,
        // A terminal successor resets this gate while it is still fenced.
        // It is enabled only by the broker-admission activation cut.
        pending_traffic_observation_gate: Option<u64>,
        // The exact odd generation written by a completed successor
        // activation. Same-process response-loss retries must read back this
        // precise generation and never infer activity from an arbitrary odd
        // value.
        active_traffic_observation_gate: Option<u64>,
        // Set only when this runtime itself created the grouped graph's pins
        // and hooks.  It is consumed by the first marker-mint attempt and is
        // cleared by any unbound operation, so a retained or observed graph
        // can never be recast as a fresh selector namespace.
        selector_namespace_fresh_provisioning: bool,
        // The original process-lifetime lease remains host-global across pod
        // network namespaces. RFC 016 operations additionally take a bounded
        // flock on a distinct namespace-derived inode, so releasing an effect
        // never releases the single-writer lease.
        _reconciler_ownership: Arc<ReconcilerOwnership>,
    }

    impl std::fmt::Debug for LoadedDevice {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter
                .debug_struct("LoadedDevice")
                .field("interface", &"<redacted>")
                .field("marked_owner_count", &self.marked_owner_by_teid.len())
                .field("default_owner_count", &self.default_teid_by_ue.len())
                .field("tc_priority", &self.tc_priority)
                .field("datapath_identity", &self.datapath_identity)
                .field("cleanup_only", &self.cleanup_only)
                .field("successor_pending", &self.successor_pending)
                .field(
                    "pending_traffic_observation_gate",
                    &self.pending_traffic_observation_gate.is_some(),
                )
                .field(
                    "active_traffic_observation_gate",
                    &self.active_traffic_observation_gate.is_some(),
                )
                .field(
                    "selector_namespace_fresh_provisioning",
                    &self.selector_namespace_fresh_provisioning,
                )
                .finish_non_exhaustive()
        }
    }

