    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    struct LegacyV2ProgramTags {
        sha1: u64,
        sha256: u64,
    }

    /// Offline tag candidates for the datapath generations this build knows by
    /// name, keyed by hook.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    struct DatapathGenerationTags {
        current: (LegacyV2ProgramTags, LegacyV2ProgramTags),
        legacy_v1: (LegacyV2ProgramTags, LegacyV2ProgramTags),
        pre_redirect: (LegacyV2ProgramTags, LegacyV2ProgramTags),
    }

    impl DatapathGenerationTags {
        /// Name the strictest generation represented by every SDK-named tc
        /// occupant on the device.
        ///
        /// Program IDs are the only trustworthy bridge between a tc dump and
        /// the loaded-program listing. Missing or ambiguous IDs make an
        /// otherwise-current inventory indeterminate. A positively identified
        /// older or unrecognised program is still authoritative refusal
        /// evidence, however, and must not be hidden by an unrelated current
        /// duplicate.
        fn classify_occupants(
            self,
            occupants: &[SdkProgramOccupant],
            loaded_program_tags: &[(u32, u64)],
        ) -> Result<Option<Generation>, GenerationIdentityEvidenceError> {
            let mut observed: Option<Generation> = None;
            let mut identity_missing = false;
            for occupant in occupants {
                let Some(program_id) = occupant.program_id else {
                    identity_missing = true;
                    continue;
                };
                let mut matches = loaded_program_tags
                    .iter()
                    .filter(|(loaded_id, _)| *loaded_id == program_id);
                let Some((_, tag)) = matches.next() else {
                    identity_missing = true;
                    continue;
                };
                if matches.next().is_some() {
                    identity_missing = true;
                    continue;
                }
                let generation = match occupant.program {
                    SdkDatapathProgram::Uplink => {
                        Self::name_hook(*tag, self.current.0, self.legacy_v1.0, self.pre_redirect.0)
                    }
                    SdkDatapathProgram::Downlink => {
                        Self::name_hook(*tag, self.current.1, self.legacy_v1.1, self.pre_redirect.1)
                    }
                };
                observed = Some(match observed {
                    Some(previous) if previous.refusal_rank() >= generation.refusal_rank() => {
                        previous
                    }
                    _ => generation,
                });
            }
            if observed.is_some_and(|generation| generation != Generation::Current) {
                return Ok(observed);
            }
            if identity_missing {
                return Err(GenerationIdentityEvidenceError);
            }
            Ok(observed)
        }

        /// Name one hook's generation from the tag the kernel reports for it.
        fn name_hook(
            tag: u64,
            current: LegacyV2ProgramTags,
            legacy_v1: LegacyV2ProgramTags,
            pre_redirect: LegacyV2ProgramTags,
        ) -> Generation {
            if current.contains(tag) {
                Generation::Current
            } else if legacy_v1.contains(tag) {
                Generation::LegacyV1
            } else if pre_redirect.contains(tag) {
                Generation::PreRedirect
            } else {
                Generation::Unrecognized
            }
        }
    }

    /// A live hook's generation as judged from its kernel program tag.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum Generation {
        Current,
        /// The frozen pre-bearer-mark generation.
        ///
        /// This build can identify its hook tags exactly, but its authentic
        /// retained graph has a narrower counter map than the current program
        /// indexes. Replacing the hooks while retaining that map would silently
        /// lose the newest counter, so this generation requires a drained
        /// reprovision just like every other superseded generation.
        LegacyV1,
        PreRedirect,
        Unrecognized,
    }

    impl Generation {
        /// Order generations by how far they are from this build.
        ///
        /// When two hooks disagree, the older or unrecognised one governs the
        /// diagnostic. Every non-current value refuses before mutation.
        const fn refusal_rank(self) -> u8 {
            match self {
                Self::Current => 0,
                Self::PreRedirect => 1,
                Self::LegacyV1 => 2,
                Self::Unrecognized => 3,
            }
        }

        /// Translate a named live generation into the public refusal evidence.
        const fn refusal(self) -> Option<EbpfDatapathGeneration> {
            match self {
                Self::Current => None,
                Self::LegacyV1 => Some(EbpfDatapathGeneration::Historical(
                    EbpfHistoricalDatapathGeneration::PreBearerMark,
                )),
                Self::PreRedirect => Some(EbpfDatapathGeneration::Historical(
                    EbpfHistoricalDatapathGeneration::PreUplinkRedirectCounter,
                )),
                Self::Unrecognized => Some(EbpfDatapathGeneration::Unrecognized),
            }
        }
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    struct GenerationIdentityEvidenceError;

    /// A cached offline tag-derivation failure.
    ///
    /// `GtpuError` carries an `io::Error` and cannot be cloned out of a cache,
    /// but every derivation failure is fully described by its stable operation
    /// label, so the cache stores that and rebuilds the error per caller.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum ObjectTagFailure {
        Parse(&'static str),
        Indeterminate(&'static str),
    }

    impl ObjectTagFailure {
        fn to_error(self) -> GtpuError {
            match self {
                Self::Parse(operation) => {
                    GtpuError::io(operation, invalid_data("bpf object parse failed"))
                }
                Self::Indeterminate(operation) => state_indeterminate(operation),
            }
        }
    }

    impl LegacyV2ProgramTags {
        fn contains(self, tag: u64) -> bool {
            tag == self.sha1 || tag == self.sha256
        }
    }

