        fn default_ue_for_teid(
            &self,
            ifindex: u32,
            local_teid: [u8; 4],
        ) -> Result<Option<[u8; 4]>, GtpuError> {
            self.with_device(ifindex, "ebpf_default_ue_for_teid", |device| {
                Ok(device
                    .default_teid_by_ue
                    .iter()
                    .find_map(|(ue_ip, teid)| (*teid == local_teid).then_some(*ue_ip)))
            })
        }

        fn default_selector_insert(
            &self,
            ifindex: u32,
            ue_ip: [u8; 4],
            local_teid: [u8; 4],
        ) -> Result<(), GtpuError> {
            self.with_device(ifindex, "ebpf_default_selector_insert", |device| {
                if ue_ip == [0; 4] || local_teid == [0; 4] {
                    return Err(state_indeterminate("ebpf_default_selector_insert"));
                }
                if device
                    .default_teid_by_ue
                    .get(&ue_ip)
                    .is_some_and(|existing| *existing != local_teid)
                    || device
                        .default_teid_by_ue
                        .iter()
                        .any(|(existing_ue, existing_teid)| {
                            *existing_teid == local_teid && *existing_ue != ue_ip
                        })
                    || device.marked_owner_by_teid.contains_key(&local_teid)
                {
                    return Err(GtpuError::AlreadyExists);
                }
                device.default_teid_by_ue.insert(ue_ip, local_teid);
                Ok(())
            })
        }

        fn default_selector_remove(
            &self,
            ifindex: u32,
            ue_ip: [u8; 4],
            local_teid: [u8; 4],
        ) -> Result<bool, GtpuError> {
            self.with_device(
                ifindex,
                "ebpf_default_selector_remove",
                |device| match device.default_teid_by_ue.get(&ue_ip) {
                    None => Ok(false),
                    Some(existing) if *existing == local_teid => {
                        device.default_teid_by_ue.remove(&ue_ip);
                        Ok(true)
                    }
                    Some(_) => Err(state_indeterminate("ebpf_default_selector_remove")),
                },
            )
        }

        fn next_session_transaction_id(&self) -> Result<GtpuSessionTransactionId, GtpuError> {
            let mut rng = SysRng;
            for _ in 0..4 {
                let mut value = [0_u8; GTPU_SESSION_GROUP_ID_LEN];
                rng.try_fill_bytes(&mut value).map_err(|_| {
                    GtpuError::io(
                        "ebpf_grouped_transaction_entropy",
                        io::Error::other("system random source unavailable"),
                    )
                })?;
                if let Some(token) = GtpuSessionTransactionId::new(value) {
                    return Ok(token);
                }
            }
            Err(state_indeterminate("ebpf_grouped_transaction_entropy"))
        }

        fn selector_namespace_pin_commitment(&self, ifindex: u32) -> Result<[u8; 32], GtpuError> {
            self.with_current_selector_namespace_control_lock(
                ifindex,
                "ebpf_selector_bootstrap_pin",
                |device, _| {
                    (device._reconciler_ownership.namespace_hash != [0; 32])
                        .then_some(device._reconciler_ownership.namespace_hash)
                        .ok_or_else(|| state_indeterminate("ebpf_selector_bootstrap_pin"))
                },
            )
        }

