        fn instruction(code: u8, dst: u8, src: u8, off: i16, imm: i32) -> bpf_insn {
            bpf_insn {
                code,
                _bitfield_align_1: [],
                _bitfield_1: bpf_insn::new_bitfield_1(dst, src),
                off,
                imm,
            }
        }

