        /// The privileged counterpart of the unprivileged capability tests:
        /// on a node that can actually load, the probe must say Loadable and
        /// must leave nothing behind.
        #[test]
        #[ignore = "requires CAP_BPF and writable bpffs"]
        fn committed_classifier_load_capability_is_loadable_and_leaves_no_state() {
            if std::env::var("OPC_GTPU_RUN_PRIVILEGED").as_deref() != Ok("1") {
                return;
            }
            let pin_root = std::path::Path::new("/sys/fs/bpf");
            let before = bpffs_entries(pin_root);

            let capability = crate::probe_committed_classifier_load(pin_root);
            assert_eq!(
                capability,
                crate::ClassifierLoadCapability::Loadable,
                "committed classifiers must load on a kernel the gate accepts"
            );
            assert!(capability.is_loadable());

            // No pin directory, no leftover maps: the probe is safe to run on
            // a node that is about to carry traffic.
            assert_eq!(
                bpffs_entries(pin_root),
                before,
                "the probe must not leave any pinned object behind"
            );
            // The CI gate greps for this. Without it a silently skipped run
            // still prints "1 passed", so the gate could go green having
            // loaded nothing.
            println!("OPC_GTPU_LOAD_CAPABILITY_PROVEN");
        }

        #[test]
        fn current_object_has_exactly_the_named_pinned_map_graph() {
            AyaGtpuRuntime::current_artifact_tags_from(DATAPATH_OBJECT)
                .expect("current object must contain only its exact named pinned map graph");
            let object = AyaObject::parse(DATAPATH_OBJECT).expect("parse current datapath object");
            assert_eq!(object.maps.len(), CURRENT_MAP_NAMES.len());
            for name in CURRENT_MAP_NAMES {
                let map = object.maps.get(name).expect("current named map");
                let expected = if name == GTPU_TRAFFIC_OBSERVATION_SEQUENCE_LOCK_MAP_NAME {
                    // BTF maps cannot carry legacy map-def pinning metadata.
                    // The loader supplies this one exact pin path explicitly.
                    PinningType::None
                } else {
                    PinningType::ByName
                };
                assert_eq!(map.pinning(), expected, "map {name}");
            }
        }

        fn bpffs_entries(pin_root: &std::path::Path) -> Vec<std::ffi::OsString> {
            let Ok(entries) = fs::read_dir(pin_root) else {
                return Vec::new();
            };
            let mut names: Vec<_> = entries
                .filter_map(|entry| entry.ok().map(|entry| entry.file_name()))
                .collect();
            names.sort();
            names
        }

        #[test]
        #[ignore = "requires CAP_BPF and writable bpffs"]
        fn program_tag_candidates_match_the_running_kernel() {
            if std::env::var("OPC_GTPU_RUN_PRIVILEGED").as_deref() != Ok("1") {
                return;
            }
            let pin_dir = std::path::PathBuf::from(format!(
                "/sys/fs/bpf/opc-gtpu-tag-proof-{}",
                std::process::id()
            ));
            fs::create_dir_all(&pin_dir).expect("create live tag proof pin directory");
            let object = AyaObject::parse(DATAPATH_OBJECT).expect("parse current datapath object");
            let (uplink_tags, downlink_tags) = AyaGtpuRuntime::object_program_tags(object)
                .expect("derive current object tag candidates");
            let mut ebpf = EbpfLoader::new()
                .default_map_pin_directory(&pin_dir)
                .load(DATAPATH_OBJECT)
                .expect("load current datapath object for live tag proof");
            for (name, expected) in [(PROG_UPLINK, uplink_tags), (PROG_DOWNLINK, downlink_tags)] {
                let program: &mut SchedClassifier = ebpf
                    .program_mut(name)
                    .expect("current tc program")
                    .try_into()
                    .expect("current program is a tc classifier");
                program.load().expect("load current tc program");
                let live_tag = program.info().expect("read live program info").tag();
                assert!(
                    expected.contains(live_tag),
                    "running-kernel tag must be one exact normalized candidate"
                );
            }
            drop(ebpf);
            fs::remove_dir_all(&pin_dir).expect("remove live tag proof pins");
            println!("OPC_GTPU_TAG_PROOF_PROVEN");
        }

        /// The whole generation guard rests on the two frozen objects having
        /// genuinely different tags. A fixture that reproduces an old map
        /// *shape* out of the current object cannot make this assertion, which
        /// is exactly why it cannot stand in for an old *generation*.
        #[test]
        fn pre_redirect_tag_candidates_differ_from_the_current_object() {
            let tags = AyaGtpuRuntime::datapath_generation_tags()
                .expect("derive tag candidates for every frozen generation");
            for (current, historical) in [
                (tags.current.0, tags.pre_redirect.0),
                (tags.current.1, tags.pre_redirect.1),
            ] {
                assert_ne!(current.sha1, historical.sha1);
                assert_ne!(current.sha256, historical.sha256);
                assert!(!current.contains(historical.sha1));
                assert!(!current.contains(historical.sha256));
                assert!(!historical.contains(current.sha1));
                assert!(!historical.contains(current.sha256));
            }
        }

        /// The frozen v1 program tags are useful refusal evidence, not
        /// migration authority: its real counter map cannot satisfy the
        /// current program's capacity contract.
        #[test]
        fn frozen_v1_counter_capacity_requires_drained_reprovision() {
            assert_eq!(
                &Sha256::digest(LEGACY_V1_DATAPATH_OBJECT)[..],
                &LEGACY_V1_DATAPATH_SHA256,
                "the embedded bytes must match the reviewed v1 artifact"
            );
            let object =
                AyaObject::parse(LEGACY_V1_DATAPATH_OBJECT).expect("parse frozen v1 object");
            let frozen = object
                .maps
                .get(MAP_COUNTERS)
                .expect("frozen v1 counter map");
            let current = CURRENT_MAP_SPECS
                .iter()
                .find(|spec| spec.name == MAP_COUNTERS)
                .expect("current counter map specification");

            assert_eq!(
                frozen.max_entries(),
                LEGACY_V1_COUNTER_SLOTS,
                "the fixture must retain the authentic v1 counter width"
            );
            assert_eq!(
                current.max_entries, COUNTER_SLOTS,
                "the runtime specification must follow the common counter ABI"
            );
            assert_ne!(
                frozen.max_entries(),
                current.max_entries,
                "a frozen v1 graph must not be admitted to the current loader"
            );

            let mut tampered = LEGACY_V1_DATAPATH_OBJECT.to_vec();
            tampered[0] ^= 0xff;
            assert!(matches!(
                AyaGtpuRuntime::legacy_v1_artifact_tags_from(&tampered),
                Err(GtpuError::StateIndeterminate {
                    operation: "ebpf_legacy_object_provenance"
                })
            ));
        }

        /// Every generation the classifier can name must be separable from
        /// every other one. Two generations sharing a tag candidate would make
        /// the guard either refuse a supported upgrade or admit an unsupported
        /// one, depending on which arm matched first.
        #[test]
        fn every_named_generation_has_distinct_tag_candidates() {
            let tags = AyaGtpuRuntime::datapath_generation_tags()
                .expect("derive tag candidates for every frozen generation");
            let generations = [
                ("current", tags.current),
                ("legacy_v1", tags.legacy_v1),
                ("pre_redirect", tags.pre_redirect),
            ];
            for (left_name, left) in generations {
                for (right_name, right) in generations {
                    if left_name == right_name {
                        continue;
                    }
                    for (left_hook, right_hook) in [(left.0, right.0), (left.1, right.1)] {
                        assert!(
                            !left_hook.contains(right_hook.sha1)
                                && !left_hook.contains(right_hook.sha256),
                            "{left_name} and {right_name} share a tag candidate"
                        );
                    }
                }
            }
        }

        fn synthetic_generation_tags() -> DatapathGenerationTags {
            let pair = |base: u64| {
                (
                    LegacyV2ProgramTags {
                        sha1: base,
                        sha256: base + 1,
                    },
                    LegacyV2ProgramTags {
                        sha1: base + 2,
                        sha256: base + 3,
                    },
                )
            };
            DatapathGenerationTags {
                current: pair(0x10),
                legacy_v1: pair(0x20),
                pre_redirect: pair(0x30),
            }
        }

        fn synthetic_occupant(
            program: SdkDatapathProgram,
            program_id: Option<u32>,
        ) -> SdkProgramOccupant {
            SdkProgramOccupant {
                program,
                parent: program.expected_parent(),
                chain: 0,
                protocol: TC_PROTOCOL_ALL,
                priority: crate::ebpf::DEFAULT_TC_PRIORITY,
                handle: u32::from(TC_HANDLE),
                program_id,
            }
        }

        #[test]
        fn sdk_named_generation_owner_without_program_id_fails_closed() {
            let missing_id = synthetic_occupant(SdkDatapathProgram::Uplink, None);
            assert_eq!(
                synthetic_generation_tags().classify_occupants(&[missing_id], &[(17, 0x10)]),
                Err(GenerationIdentityEvidenceError)
            );
            assert_eq!(
                SdkDatapathProgram::from_filter_name("foreign_classifier"),
                None,
                "a foreign hook is not a generation question"
            );
        }

        #[test]
        fn generation_program_id_absent_from_loaded_listing_fails_closed() {
            let occupant = synthetic_occupant(SdkDatapathProgram::Uplink, Some(18));
            let tags = synthetic_generation_tags();
            assert_eq!(
                tags.classify_occupants(std::slice::from_ref(&occupant), &[(17, 0x10), (19, 0x11)]),
                Err(GenerationIdentityEvidenceError)
            );
            assert_eq!(
                tags.classify_occupants(&[occupant], &[(18, 0x10), (18, 0x10)]),
                Err(GenerationIdentityEvidenceError),
                "duplicate listing evidence is ambiguous"
            );
        }

        /// Every hook this build can identify is named. Only current hooks are
        /// admitted; every older or unknown instruction stream must produce
        /// explicit refusal evidence before the loader publishes a map.
        #[test]
        fn generation_classification_names_every_refusal() {
            let tags = synthetic_generation_tags();

            assert_eq!(Generation::Current.refusal(), None);
            assert_eq!(
                Generation::LegacyV1.refusal(),
                Some(EbpfDatapathGeneration::Historical(
                    EbpfHistoricalDatapathGeneration::PreBearerMark
                ))
            );
            assert_eq!(
                Generation::PreRedirect.refusal(),
                Some(EbpfDatapathGeneration::Historical(
                    EbpfHistoricalDatapathGeneration::PreUplinkRedirectCounter
                ))
            );
            assert_eq!(
                Generation::Unrecognized.refusal(),
                Some(EbpfDatapathGeneration::Unrecognized)
            );

            assert_eq!(tags.classify_occupants(&[], &[]), Ok(None));

            let uplink = synthetic_occupant(SdkDatapathProgram::Uplink, Some(1));
            let downlink = synthetic_occupant(SdkDatapathProgram::Downlink, Some(2));
            for (uplink_tag, downlink_tag, expected) in [
                (0x10, 0x12, Generation::Current),
                (0x11, 0x13, Generation::Current),
                (0x20, 0x22, Generation::LegacyV1),
                (0x30, 0x32, Generation::PreRedirect),
                (0x31, 0x33, Generation::PreRedirect),
                (0x10, 0x32, Generation::PreRedirect),
                (0x30, 0x22, Generation::LegacyV1),
                (0x10, 0x99, Generation::Unrecognized),
            ] {
                assert_eq!(
                    tags.classify_occupants(
                        &[uplink.clone(), downlink.clone()],
                        &[(1, uplink_tag), (2, downlink_tag)]
                    ),
                    Ok(Some(expected)),
                    "uplink {uplink_tag:#x} downlink {downlink_tag:#x}"
                );
            }

            // A single occupied hook is sufficient evidence.
            assert_eq!(
                tags.classify_occupants(&[uplink], &[(1, 0x30)]),
                Ok(Some(Generation::PreRedirect))
            );
        }

        #[test]
        fn multiple_sdk_occupants_are_classified_deterministically() {
            let tags = synthetic_generation_tags();
            let current = synthetic_occupant(SdkDatapathProgram::Uplink, Some(1));
            let historical = synthetic_occupant(SdkDatapathProgram::Downlink, Some(2));
            let unknown = synthetic_occupant(SdkDatapathProgram::Uplink, Some(3));
            let listing = [(1, 0x10), (2, 0x32), (3, 0x99)];

            for occupants in [
                vec![current.clone(), historical.clone(), unknown.clone()],
                vec![unknown.clone(), current.clone(), historical.clone()],
                vec![historical.clone(), unknown.clone(), current.clone()],
            ] {
                assert_eq!(
                    tags.classify_occupants(&occupants, &listing),
                    Ok(Some(Generation::Unrecognized)),
                    "the strictest refusal must not depend on dump ordering"
                );
            }

            let missing = synthetic_occupant(SdkDatapathProgram::Uplink, None);
            assert_eq!(
                tags.classify_occupants(&[missing, historical], &listing),
                Ok(Some(Generation::PreRedirect)),
                "positive historical evidence must dominate a current-placement question"
            );
        }

        #[test]
        fn current_duplicates_and_wrong_map_graphs_are_conflicts() {
            let priority = crate::ebpf::DEFAULT_TC_PRIORITY;
            let uplink = CurrentSdkProgram {
                occupant: synthetic_occupant(SdkDatapathProgram::Uplink, Some(1)),
                program_tag: 0x11,
                map_ids: vec![1, 2],
            };
            let downlink = CurrentSdkProgram {
                occupant: synthetic_occupant(SdkDatapathProgram::Downlink, Some(2)),
                program_tag: 0x22,
                map_ids: vec![2, 3],
            };
            assert_eq!(
                validate_current_program_placement(
                    &[uplink.occupant.clone(), downlink.occupant.clone()],
                    priority
                ),
                Ok(())
            );
            assert_eq!(
                validate_current_program_graph_placement(
                    &[uplink.occupant.clone(), downlink.occupant.clone()],
                    priority,
                    1,
                    2,
                ),
                Ok(()),
                "a live graph requires the complete canonical pair with exact IDs"
            );
            assert_eq!(
                validate_current_program_map_graph(&uplink, Some(&[1, 2])),
                Ok(())
            );
            assert_eq!(
                validate_current_program_map_graph(&downlink, Some(&[2, 3])),
                Ok(())
            );

            let mut extra = uplink.occupant.clone();
            extra.priority += 1;
            for programs in [
                vec![
                    uplink.occupant.clone(),
                    extra.clone(),
                    downlink.occupant.clone(),
                ],
                vec![downlink.occupant.clone(), extra, uplink.occupant.clone()],
            ] {
                assert_eq!(
                    validate_current_program_placement(&programs, priority),
                    Err(CurrentProgramGraphConflict),
                    "a duplicate outside the desired slot must conflict in any order"
                );
                assert_eq!(
                    validate_current_program_graph_placement(&programs, priority, 1, 2),
                    Err(CurrentProgramGraphConflict),
                    "a live graph must reject every off-slot duplicate"
                );
            }
            let mut nondefault_chain = downlink.occupant.clone();
            nondefault_chain.chain = 1;
            assert_eq!(
                validate_current_program_placement(
                    &[uplink.occupant.clone(), nondefault_chain.clone()],
                    priority
                ),
                Err(CurrentProgramGraphConflict)
            );
            assert_eq!(
                validate_current_program_graph_placement(
                    &[uplink.occupant.clone(), nondefault_chain],
                    priority,
                    1,
                    2,
                ),
                Err(CurrentProgramGraphConflict),
                "a live graph must reject a current program on a non-default chain"
            );
            for (programs, uplink_id, downlink_id) in [
                (vec![uplink.occupant.clone()], 1, 2),
                (
                    vec![uplink.occupant.clone(), downlink.occupant.clone()],
                    9,
                    2,
                ),
                (
                    vec![uplink.occupant.clone(), downlink.occupant.clone()],
                    1,
                    9,
                ),
            ] {
                assert_eq!(
                    validate_current_program_graph_placement(
                        &programs,
                        priority,
                        uplink_id,
                        downlink_id,
                    ),
                    Err(CurrentProgramGraphConflict),
                    "a live graph must require both exact loaded program identities"
                );
            }

            assert_eq!(
                validate_current_program_map_graph(&uplink, Some(&[1, 9])),
                Err(CurrentProgramGraphConflict)
            );
            assert_eq!(
                validate_current_program_map_graph(&uplink, None),
                Err(CurrentProgramGraphConflict),
                "a current hook without a named graph is already owned elsewhere"
            );
        }

        #[test]
        #[ignore = "requires CAP_BPF and writable bpffs"]
        fn pre_redirect_tag_candidates_match_the_running_kernel() {
            if std::env::var("OPC_GTPU_RUN_PRIVILEGED").as_deref() != Ok("1") {
                return;
            }
            let pin_dir = std::path::PathBuf::from(format!(
                "/sys/fs/bpf/opc-gtpu-pre-redirect-tag-proof-{}",
                std::process::id()
            ));
            fs::create_dir_all(&pin_dir).expect("create pre-redirect tag proof pin directory");
            let tags = AyaGtpuRuntime::datapath_generation_tags()
                .expect("derive tag candidates for both frozen generations");
            let mut ebpf = EbpfLoader::new()
                .default_map_pin_directory(&pin_dir)
                .load(pre_redirect_artifact::object_for_tag_proof())
                .expect("load pre-redirect datapath object for live tag proof");
            for (name, expected) in [
                (PROG_UPLINK, tags.pre_redirect.0),
                (PROG_DOWNLINK, tags.pre_redirect.1),
            ] {
                let program: &mut SchedClassifier = ebpf
                    .program_mut(name)
                    .expect("pre-redirect tc program")
                    .try_into()
                    .expect("pre-redirect program is a tc classifier");
                program.load().expect("load pre-redirect tc program");
                let live_tag = program.info().expect("read live program info").tag();
                assert!(
                    expected.contains(live_tag),
                    "running-kernel tag must be one exact normalized candidate"
                );
            }
            drop(ebpf);
            fs::remove_dir_all(&pin_dir).expect("remove pre-redirect tag proof pins");
            println!("OPC_GTPU_PRE_REDIRECT_TAG_PROOF_PROVEN");
        }

