        #[test]
        #[ignore = "requires CAP_BPF/CAP_NET_ADMIN, writable bpffs, and a fresh netns"]
        fn historical_25_attached_frozen_graph_is_refused_without_mutation() {
            use std::os::unix::fs::{MetadataExt, PermissionsExt};

            if std::env::var("OPC_GTPU_RUN_PRIVILEGED").as_deref() != Ok("1") {
                return;
            }
            let sequence = CAPABILITY_PROBE_SEQUENCE.fetch_add(1, Ordering::Relaxed);
            let pin_root = PathBuf::from(format!(
                "/sys/fs/bpf/opc-gtpu-historical-25-attached-{}-{sequence}",
                std::process::id()
            ));
            fs::create_dir(&pin_root).expect("create unique attached-history root");
            struct ExactRootCleanup(PathBuf);
            impl Drop for ExactRootCleanup {
                fn drop(&mut self) {
                    let _ = fs::remove_dir_all(&self.0);
                }
            }
            let _cleanup = ExactRootCleanup(pin_root.clone());
            fs::set_permissions(&pin_root, fs::Permissions::from_mode(0o755))
                .expect("reproduce the shipped namespace-root mode");

            let pin_dir = pin_root.join("up0");
            assert!(
                sys::ifindex_by_name("up0").is_err(),
                "the old Multus interface must be absent in the fresh namespace"
            );
            fs::create_dir(&pin_dir).expect("create historical graph namespace");
            fs::set_permissions(&pin_dir, fs::Permissions::from_mode(0o755))
                .expect("reproduce the shipped graph mode");
            let mut ebpf = EbpfLoader::new()
                .default_map_pin_directory(&pin_dir)
                .load(
                    pre_selector_stamp_traffic_observation_v1_artifact::object_for_privileged_generation_harness(),
                )
                .expect("load exact frozen 25-map object");
            {
                let map = ebpf
                    .map_mut(MAP_CONFIG)
                    .expect("frozen historical local-address map");
                let mut config = Array::<_, [u8; 4]>::try_from(map)
                    .expect("typed frozen historical local-address map");
                config
                    .set(0, [192, 0, 2, 1], 0)
                    .expect("seed the formerly shipped local-address slot");
            }
            AyaGtpuRuntime::write_bearer_schema_marker(&mut ebpf)
                .expect("seed the shipped schema marker");

            let replacement_ifindex =
                sys::ifindex_by_name("lo").expect("replacement loopback identity");
            if let Err(error) = tc::qdisc_add_clsact("lo") {
                assert!(
                    is_qdisc_already_present(&error),
                    "create replacement clsact qdisc: {error}"
                );
            }
            let attach = |ebpf: &mut Ebpf, name, attach_type| {
                let program: &mut SchedClassifier = ebpf
                    .program_mut(name)
                    .expect("historical tc program")
                    .try_into()
                    .expect("historical program is a tc classifier");
                program.load().expect("load historical tc program");
                let program_id = program.info().expect("live program info").id();
                program
                    .attach_with_options(
                        "lo",
                        attach_type,
                        TcAttachOptions::Netlink(NlOptions {
                            priority: 50,
                            handle: TC_HANDLE,
                            classid: None,
                        }),
                    )
                    .expect("attach exact historical tc hook");
                program_id
            };
            let uplink_program_id = attach(&mut ebpf, PROG_UPLINK, TcAttachType::Egress);
            let downlink_program_id = attach(&mut ebpf, PROG_DOWNLINK, TcAttachType::Ingress);

            let control_root = pin_root.join(RECONCILER_CONTROL_DIRECTORY);
            fs::create_dir(&control_root).expect("create predecessor authority root");
            fs::set_permissions(&control_root, fs::Permissions::from_mode(0o755))
                .expect("reproduce predecessor authority-root mode");
            let legacy_leaf = control_root.join(
                AyaGtpuRuntime::historical_25_legacy_leaf_name(pin_dir.file_name().unwrap())
                    .expect("legacy up0 authority leaf"),
            );
            fs::create_dir(&legacy_leaf).expect("create exact legacy authority leaf");
            fs::set_permissions(&legacy_leaf, fs::Permissions::from_mode(0o755))
                .expect("reproduce shipped authority-leaf mode");
            let graph_metadata = fs::metadata(&pin_dir).expect("historical graph metadata");
            assert_eq!(
                AyaGtpuRuntime::historical_25_named_map_ids(
                    &pin_dir,
                    (graph_metadata.dev(), graph_metadata.ino()),
                )
                .expect("exact frozen 25-map graph")
                .len(),
                25
            );
            let control_inventory = fs::read_dir(&control_root)
                .expect("inventory predecessor authority")
                .map(|entry| entry.expect("read predecessor authority entry").file_name())
                .collect::<Vec<_>>();

            let runtime = AyaGtpuRuntime::new();
            assert_eq!(
                runtime
                    .recover_orphaned_historical_graph(
                        HistoricalEbpfGraphGeneration::PreSessionSelectorStampTrafficObservationV1,
                        Some(("lo", replacement_ifindex)),
                        &pin_dir,
                        50,
                        true,
                        CurrentRecoveryManagedState::Clear,
                        super::super::test_historical_ebpf_graph_recovery_authority_binding(),
                        &super::super::TestHistoricalEbpfGraphRecoveryCurrentness,
                    )
                    .expect("attached historical graph refusal must stay typed"),
                HistoricalEbpfGraphRecoveryOutcome::Refused(
                    HistoricalEbpfGraphRecoveryRefusal::ActiveHistoricalAttachment
                )
            );
            assert_eq!(
                fs::read_dir(&pin_dir)
                    .expect("attached historical graph remains")
                    .count(),
                25
            );
            assert_eq!(
                fs::read_dir(&control_root)
                    .expect("re-inventory predecessor authority")
                    .map(|entry| entry.expect("read predecessor authority entry").file_name())
                    .collect::<Vec<_>>(),
                control_inventory
            );
            assert!(legacy_leaf.exists());
            assert!(matches!(
                slot_owner(replacement_ifindex, TcAttachType::Egress, 50),
                Ok(Some(owner))
                    if owner.name == PROG_UPLINK && owner.program_id == Some(uplink_program_id)
            ));
            assert!(matches!(
                slot_owner(replacement_ifindex, TcAttachType::Ingress, 50),
                Ok(Some(owner))
                    if owner.name == PROG_DOWNLINK && owner.program_id == Some(downlink_program_id)
            ));
            drop(ebpf);
            println!("OPC_GTPU_HISTORICAL_25_ATTACHED_REFUSAL_PROVEN");
        }

        #[test]
        #[ignore = "requires CAP_BPF/CAP_NET_ADMIN, writable bpffs, iproute2, and a fresh netns"]
        fn historical_25_detached_frozen_graph_resumes_after_up0_name_reuse_with_new_ifindex() {
            use std::os::unix::fs::{MetadataExt, PermissionsExt};

            if std::env::var("OPC_GTPU_RUN_PRIVILEGED").as_deref() != Ok("1") {
                return;
            }
            struct Up0Cleanup;
            impl Drop for Up0Cleanup {
                fn drop(&mut self) {
                    let _ = std::process::Command::new("ip")
                        .args(["link", "del", "up0"])
                        .output();
                }
            }
            let run_ip = |arguments: &[&str]| {
                let output = std::process::Command::new("ip")
                    .args(arguments)
                    .output()
                    .unwrap_or_else(|error| panic!("run ip for exact up0 lifecycle: {error}"));
                assert!(
                    output.status.success(),
                    "exact up0 lifecycle command failed: {}",
                    String::from_utf8_lossy(&output.stderr)
                );
            };
            assert!(
                sys::ifindex_by_name("up0").is_err(),
                "the privileged causal harness requires a fresh namespace without a pre-existing up0"
            );
            run_ip(&["link", "add", "up0", "type", "dummy"]);
            let _up0_cleanup = Up0Cleanup;
            let old_up0_ifindex =
                sys::ifindex_by_name("up0").expect("old Multus-style up0 identity");
            run_ip(&["link", "set", "up0", "up"]);
            let sequence = CAPABILITY_PROBE_SEQUENCE.fetch_add(1, Ordering::Relaxed);
            let pin_root = PathBuf::from(format!(
                "/sys/fs/bpf/opc-gtpu-historical-25-detached-{}-{sequence}",
                std::process::id()
            ));
            fs::create_dir(&pin_root).expect("create unique detached-history root");
            struct ExactRootCleanup(PathBuf);
            impl Drop for ExactRootCleanup {
                fn drop(&mut self) {
                    let _ = fs::remove_dir_all(&self.0);
                }
            }
            let _cleanup = ExactRootCleanup(pin_root.clone());
            fs::set_permissions(&pin_root, fs::Permissions::from_mode(0o755))
                .expect("reproduce the shipped umask-derived namespace root");

            let pin_dir = pin_root.join("up0");
            fs::create_dir(&pin_dir).expect("create historical graph namespace");
            fs::set_permissions(&pin_dir, fs::Permissions::from_mode(0o755))
                .expect("reproduce the shipped umask-derived graph namespace");
            let mut ebpf = EbpfLoader::new()
                .default_map_pin_directory(&pin_dir)
                .load(
                    pre_selector_stamp_traffic_observation_v1_artifact::object_for_privileged_generation_harness(),
                )
                .expect("load exact frozen 25-map object without loading its programs");
            {
                let map = ebpf
                    .map_mut(MAP_CONFIG)
                    .expect("frozen historical local-address map");
                let mut config = Array::<_, [u8; 4]>::try_from(map)
                    .expect("typed frozen historical local-address map");
                config
                    .set(0, [192, 0, 2, 1], 0)
                    .expect("seed the formerly shipped local-address slot");
            }
            AyaGtpuRuntime::write_bearer_schema_marker(&mut ebpf)
                .expect("seed the shipped schema marker");
            drop(ebpf);
            let graph_metadata = fs::metadata(&pin_dir).expect("historical graph metadata");
            assert_eq!(
                AyaGtpuRuntime::historical_25_named_map_ids(
                    &pin_dir,
                    (graph_metadata.dev(), graph_metadata.ino()),
                )
                .expect("exact frozen 25-map graph")
                .len(),
                25
            );

            let control_root = pin_root.join(RECONCILER_CONTROL_DIRECTORY);
            fs::create_dir(&control_root).expect("create predecessor authority root");
            fs::set_permissions(&control_root, fs::Permissions::from_mode(0o755))
                .expect("reproduce predecessor umask-derived root mode");
            let legacy_leaf = control_root.join(
                AyaGtpuRuntime::historical_25_legacy_leaf_name(pin_dir.file_name().unwrap())
                    .expect("legacy up0 authority leaf"),
            );
            fs::create_dir(&legacy_leaf).expect("create exact legacy authority leaf");
            fs::set_permissions(&legacy_leaf, fs::Permissions::from_mode(0o755))
                .expect("reproduce the shipped umask-derived authority leaf");

            // Model the incident precisely: the original Multus up0 has gone
            // away, then a new pod-local up0 reuses its name under a distinct
            // ifindex.  The retained 25-map graph has no live hooks or owner.
            run_ip(&["link", "del", "up0"]);
            assert!(
                sys::ifindex_by_name("up0").is_err(),
                "old up0 must be absent before the replacement is created"
            );
            run_ip(&["link", "add", "up0", "type", "dummy"]);
            let replacement_ifindex =
                sys::ifindex_by_name("up0").expect("replacement up0 identity must resolve");
            assert_ne!(old_up0_ifindex, replacement_ifindex);
            run_ip(&["link", "set", "up0", "up"]);
            let runtime = AyaGtpuRuntime::new();
            let exact_historical_inspection = match runtime
                .inspect_orphaned_historical_graph(
                    HistoricalEbpfGraphGeneration::PreSessionSelectorStampTrafficObservationV1,
                    Some(("up0", replacement_ifindex)),
                    &pin_dir,
                    50,
                    super::super::test_historical_ebpf_graph_recovery_authority_binding(),
                    &super::super::TestHistoricalEbpfGraphRecoveryCurrentness,
                )
                .expect("inspect the authentic detached shipped-25 graph before recovery")
            {
                HistoricalEbpfGraphRecoveryInspectionOutcome::ExactDetached(inspection) => {
                    inspection
                }
                outcome => panic!("expected exact detached shipped-25 inspection, got {outcome:?}"),
            };
            let exact_historical_authority =
                super::super::test_historical_ebpf_graph_recovery_authority_binding_for_inspection(
                    exact_historical_inspection,
                );
            let control_inventory = || {
                let mut entries = fs::read_dir(&control_root)
                    .expect("inventory predecessor authority root")
                    .map(|entry| entry.expect("read predecessor authority entry").file_name())
                    .collect::<Vec<_>>();
                entries.sort_unstable();
                entries
            };
            let expected_control_inventory = control_inventory();
            for root_mode in [0o755, 0o700] {
                fs::set_permissions(&control_root, fs::Permissions::from_mode(root_mode))
                    .expect("select an authentic predecessor authority-root mode");
                assert_eq!(
                    runtime
                        .recover_orphaned_current_graph(
                            Some(("up0", replacement_ifindex)),
                            &pin_dir,
                            50,
                            true,
                            CurrentRecoveryManagedState::Clear,
                            super::super::test_current_ebpf_graph_recovery_authority_binding(),
                            &super::super::TestCurrentEbpfGraphRecoveryCurrentness,
                        )
                        .expect("current recovery must retain a typed generation refusal"),
                    CurrentEbpfGraphRecoveryOutcome::Refused(
                        CurrentEbpfGraphRecoveryRefusal::NotCurrentSchema
                    ),
                    "authentic predecessor root mode {root_mode:o}"
                );
                assert_eq!(
                    control_inventory(),
                    expected_control_inventory,
                    "generation classification must not manufacture current authority for mode {root_mode:o}"
                );
            }
            let config_pin = pin_dir.join(MAP_CONFIG);
            fs::set_permissions(&config_pin, fs::Permissions::from_mode(0o640))
                .expect("make one authentic graph pin authority-indeterminate");
            assert_eq!(
                runtime
                    .recover_orphaned_historical_graph(
                        HistoricalEbpfGraphGeneration::PreSessionSelectorStampTrafficObservationV1,
                        Some(("up0", replacement_ifindex)),
                        &pin_dir,
                        50,
                        true,
                        CurrentRecoveryManagedState::Clear,
                        exact_historical_authority,
                        &super::super::TestHistoricalEbpfGraphRecoveryCurrentness,
                    )
                    .expect("wrong-mode graph pin must fail closed as a typed refusal"),
                HistoricalEbpfGraphRecoveryOutcome::Refused(
                    HistoricalEbpfGraphRecoveryRefusal::IndeterminateState
                )
            );
            assert_eq!(
                fs::read_dir(&pin_dir)
                    .expect("historical graph remains after refusal")
                    .count(),
                25
            );
            fs::set_permissions(&config_pin, fs::Permissions::from_mode(0o600))
                .expect("restore exact shipped BPF pin mode for retry");
            HISTORICAL_25_TEST_CRASH_AFTER_INSTALLED_STAGING.with(|armed| armed.set(true));
            let interrupted = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                runtime
                    .recover_orphaned_historical_graph(
                        HistoricalEbpfGraphGeneration::PreSessionSelectorStampTrafficObservationV1,
                        Some(("up0", replacement_ifindex)),
                        &pin_dir,
                        50,
                        true,
                        CurrentRecoveryManagedState::Clear,
                        exact_historical_authority,
                        &super::super::TestHistoricalEbpfGraphRecoveryCurrentness,
                    )
                    .expect("reach the exact post-Installed pre-rename crash cut")
            }));
            assert!(
                interrupted.is_err(),
                "the production-path crash cut must be reached"
            );
            let (legacy_receipt_path, staging_receipt_path) = {
                let legacy = AyaGtpuRuntime::acquire_historical_25_legacy_ownership(&pin_dir)
                    .expect("reacquire the predecessor authority after crash")
                    .expect("legacy authority must survive the interrupted install");
                let proof = AyaGtpuRuntime::historical_25_read_proof(&legacy)
                    .expect("read the durable legacy receipt")
                    .expect("the Installed receipt must be durable");
                assert_eq!(proof.record.phase, Historical25RecoveryPhase::Installed);
                let (_, current_leaf_name, control_root_descriptor) =
                    AyaGtpuRuntime::historical_25_current_leaf_name(
                        &pin_dir,
                        &legacy,
                        "ebpf_historical_25_test_installed_staging",
                    )
                    .expect("resolve the deterministic current namespace");
                let staging_leaf_name = AyaGtpuRuntime::historical_25_staging_leaf_name(
                    &current_leaf_name,
                    proof.record.handoff_nonce,
                );
                let entries = AyaGtpuRuntime::historical_25_control_root_entries(
                    &control_root_descriptor,
                    "ebpf_historical_25_test_installed_staging",
                )
                .expect("inventory the exact interrupted namespace");
                assert!(entries.contains(&staging_leaf_name));
                assert!(!entries.contains(&current_leaf_name));
                (
                    legacy_leaf.join(HISTORICAL_25_RECOVERY_PROOF_MAP),
                    control_root
                        .join(staging_leaf_name)
                        .join(HISTORICAL_25_ROOT_HANDOFF_MARKER),
                )
            };
            for receipt_path in [&legacy_receipt_path, &staging_receipt_path] {
                fs::set_permissions(receipt_path, fs::Permissions::from_mode(0o640))
                    .expect("make one Installed receipt authority-indeterminate");
                let outcome = runtime
                    .recover_orphaned_historical_graph(
                        HistoricalEbpfGraphGeneration::PreSessionSelectorStampTrafficObservationV1,
                        Some(("up0", replacement_ifindex)),
                        &pin_dir,
                        50,
                        true,
                        CurrentRecoveryManagedState::Clear,
                        exact_historical_authority,
                        &super::super::TestHistoricalEbpfGraphRecoveryCurrentness,
                    )
                    .expect("wrong-mode receipt must remain a typed fail-closed outcome");
                assert!(
                    matches!(
                        outcome,
                        HistoricalEbpfGraphRecoveryOutcome::Refused(
                            HistoricalEbpfGraphRecoveryRefusal::IndeterminateState
                        ) | HistoricalEbpfGraphRecoveryOutcome::Partial(
                            HistoricalEbpfGraphRecoveryProgress::Indeterminate
                        )
                    ),
                    "wrong-mode Installed receipt must not authorize a graph effect"
                );
                assert!(pin_dir.exists(), "receipt refusal must retain the graph");
                assert_eq!(
                    fs::read_dir(&pin_dir)
                        .expect("historical graph remains after receipt refusal")
                        .count(),
                    25
                );
                fs::set_permissions(receipt_path, fs::Permissions::from_mode(0o600))
                    .expect("restore exact BPF receipt mode for retry");
            }
            let final_outcome = runtime
                .recover_orphaned_historical_graph(
                    HistoricalEbpfGraphGeneration::PreSessionSelectorStampTrafficObservationV1,
                    Some(("up0", replacement_ifindex)),
                    &pin_dir,
                    50,
                    true,
                    CurrentRecoveryManagedState::Clear,
                    exact_historical_authority,
                    &super::super::TestHistoricalEbpfGraphRecoveryCurrentness,
                )
                .expect("recover exact detached historical graph");
            assert_eq!(final_outcome, HistoricalEbpfGraphRecoveryOutcome::Removed);
            assert!(
                !pin_dir.exists(),
                "all exact historical pins must be absent"
            );
            assert!(!legacy_leaf.exists(), "legacy authority must be retired");
            assert_eq!(
                runtime
                    .recover_orphaned_historical_graph(
                        HistoricalEbpfGraphGeneration::PreSessionSelectorStampTrafficObservationV1,
                        Some(("up0", replacement_ifindex)),
                        &pin_dir,
                        50,
                        true,
                        CurrentRecoveryManagedState::Clear,
                        exact_historical_authority,
                        &super::super::TestHistoricalEbpfGraphRecoveryCurrentness,
                    )
                    .expect("repeat terminal detached recovery"),
                HistoricalEbpfGraphRecoveryOutcome::AlreadyAbsent
            );
            let commitment = |byte| {
                crate::HistoricalEbpfGraphRecoveryCommitment::new([byte; 32])
                    .expect("fixed test commitment")
            };
            let transferred_authority =
                crate::HistoricalEbpfGraphRecoveryAuthorityBinding::from_parts(
                    commitment(0x91),
                    commitment(0x92),
                    exact_historical_inspection.former_link_evidence(),
                    crate::HistoricalEbpfGraphRecoveryArtifactProvenance::from_brokered_challenge(
                        commitment(0x88),
                        exact_historical_inspection.expected_challenge(),
                    ),
                    std::num::NonZeroU64::new(2).expect("nonzero transfer epoch"),
                    crate::HistoricalEbpfGraphRecoveryOperationId::new([0x93; 16])
                        .expect("fixed transfer operation"),
                    crate::HistoricalEbpfGraphRecoveryHostCommitments::new(
                        commitment(0x84),
                        commitment(0x85),
                        commitment(0x86),
                    ),
                );
            assert_eq!(
                runtime
                    .recover_orphaned_historical_graph(
                        HistoricalEbpfGraphGeneration::PreSessionSelectorStampTrafficObservationV1,
                        Some(("up0", replacement_ifindex)),
                        &pin_dir,
                        50,
                        true,
                        CurrentRecoveryManagedState::Clear,
                        transferred_authority,
                        &super::super::TestHistoricalEbpfGraphRecoveryCurrentness,
                    )
                    .expect("terminal R5 may transfer only after exact absence is re-proved"),
                HistoricalEbpfGraphRecoveryOutcome::AlreadyAbsent
            );
            let initial_current_authority =
                super::super::test_current_ebpf_graph_recovery_authority_binding();
            assert_eq!(
                runtime
                    .recover_orphaned_current_graph(
                        Some(("up0", replacement_ifindex)),
                        &pin_dir,
                        50,
                        true,
                        CurrentRecoveryManagedState::Clear,
                        initial_current_authority,
                        &super::super::TestCurrentEbpfGraphRecoveryCurrentness,
                    )
                    .expect("bridge the authentic R5 handoff into a current terminal WAL"),
                CurrentEbpfGraphRecoveryOutcome::AlreadyAbsent
            );
            let (terminal_before, terminal_identity, surviving_authority_marker) = {
                let ownership =
                    AyaGtpuRuntime::acquire_existing_reconciler_ownership_with_currentness(
                        &pin_dir,
                        &super::super::TestCurrentEbpfGraphRecoveryCurrentness,
                    )
                    .expect("open the exact retained current authority without creating state");
                let current_leaf = control_root.join(&ownership.control_dir_name);
                let terminal_path = current_leaf.join(CURRENT_RECOVERY_TERMINAL_PROOF_MAP);
                let terminal_metadata = fs::symlink_metadata(&terminal_path)
                    .expect("inspect the durable current terminal pin identity");
                let terminal = AyaGtpuRuntime::read_current_terminal_proof(&ownership)
                    .expect("read exact current terminal before refusal")
                    .expect("current terminal must exist before refusal");
                (
                    terminal,
                    (terminal_metadata.dev(), terminal_metadata.ino()),
                    current_leaf.join(format!("SELECTOR_AUTHORITY_V1_{}", "ab".repeat(32))),
                )
            };
            fs::create_dir(&surviving_authority_marker)
                .expect("reproduce one surviving exact selector authority marker");
            fs::set_permissions(
                &surviving_authority_marker,
                fs::Permissions::from_mode(0o700),
            )
            .expect("preserve exact selector authority-marker mode");
            assert_eq!(
                runtime
                    .inspect_current_recovery_terminal(
                        Some(("up0", replacement_ifindex)),
                        &pin_dir,
                        50,
                        CurrentRecoveryManagedState::Clear,
                        initial_current_authority,
                        &super::super::TestCurrentEbpfGraphRecoveryCurrentness,
                    )
                    .expect("surviving authority is a typed terminal refusal"),
                crate::CurrentEbpfGraphRecoveryTerminalInspectionOutcome::Refused(
                    CurrentEbpfGraphRecoveryRefusal::IndeterminateState
                )
            );
            {
                let ownership =
                    AyaGtpuRuntime::acquire_existing_reconciler_ownership_with_currentness(
                        &pin_dir,
                        &super::super::TestCurrentEbpfGraphRecoveryCurrentness,
                    )
                    .expect("reopen the unchanged retained authority after refusal");
                let current_leaf = control_root.join(&ownership.control_dir_name);
                let terminal_metadata =
                    fs::symlink_metadata(current_leaf.join(CURRENT_RECOVERY_TERMINAL_PROOF_MAP))
                        .expect("terminal pin must survive the refusal");
                assert_eq!(
                    (terminal_metadata.dev(), terminal_metadata.ino()),
                    terminal_identity,
                    "authority ambiguity must not replace the terminal pin"
                );
                assert_eq!(
                    AyaGtpuRuntime::read_current_terminal_proof(&ownership)
                        .expect("read current terminal after refusal"),
                    Some(terminal_before),
                    "authority ambiguity must not mutate the authenticated WAL"
                );
            }
            fs::remove_dir(&surviving_authority_marker)
                .expect("retire only the synthetic test authority marker");
            let transfer = match runtime
                .inspect_current_recovery_terminal(
                    Some(("up0", replacement_ifindex)),
                    &pin_dir,
                    50,
                    CurrentRecoveryManagedState::Clear,
                    initial_current_authority,
                    &super::super::TestCurrentEbpfGraphRecoveryCurrentness,
                )
                .expect("authenticate the real-kernel current terminal")
            {
                crate::CurrentEbpfGraphRecoveryTerminalInspectionOutcome::Authenticated(
                    transfer,
                ) => transfer,
                other => panic!("expected an authenticated current terminal, got {other:?}"),
            };
            let current_commitment = |byte| {
                crate::CurrentEbpfGraphRecoveryCommitment::new([byte; 32])
                    .expect("fixed current test commitment")
            };
            let transferred_current_authority =
                crate::CurrentEbpfGraphRecoveryAuthorityBinding::new(
                    current_commitment(0xb1),
                    transfer.predecessor_basis_commitment(),
                    std::num::NonZeroU64::new(2).expect("nonzero current transfer epoch"),
                    crate::CurrentEbpfGraphRecoveryOperationId::new([0xb3; 16])
                        .expect("fixed current transfer operation"),
                    crate::CurrentEbpfGraphRecoveryHostCommitments::new(
                        current_commitment(0x94),
                        current_commitment(0x95),
                        current_commitment(0x96),
                    ),
                );
            for attempt in 0..2 {
                let snapshot = runtime
                    .transfer_current_recovery_terminal(
                        Some(("up0", replacement_ifindex)),
                        &pin_dir,
                        50,
                        CurrentRecoveryManagedState::Clear,
                        transfer,
                        transferred_current_authority,
                        &super::super::TestCurrentEbpfGraphRecoveryCurrentness,
                    )
                    .expect("transfer the real-kernel terminal WAL");
                assert!(
                    matches!(
                        snapshot,
                        Some(super::super::CurrentEbpfGraphRecoveryTerminalSnapshot::Authenticated {
                            terminal_source:
                                crate::CurrentEbpfGraphRecoveryTerminalSource::HistoricalR5Handoff { .. },
                            terminal_adoption: Some(_),
                            ..
                        })
                    ),
                    "real-kernel terminal transfer attempt {attempt} must converge idempotently"
                );
            }
            println!("OPC_GTPU_HISTORICAL_25_CURRENT_TERMINAL_TRANSFER_PROVEN");
            println!("OPC_GTPU_HISTORICAL_25_DETACHED_RECOVERY_PROVEN");
        }

        /// Exercise the real descriptor-relative shared-root classifier with
        /// a native current namespace for tenant A and a genuinely absent
        /// historical target B.  The maintenance observation must preserve
        /// A's paired current leaf/operation lock and must not manufacture
        /// any B root, leaf, proof, or marker.
        #[test]
        #[ignore = "requires writable bpffs, an uncontended loopback tc view, and a fresh netns"]
        fn historical_25_pristine_absence_preserves_disjoint_current_namespace_on_bpffs() {
            use std::os::unix::fs::PermissionsExt;

            if std::env::var("OPC_GTPU_RUN_PRIVILEGED").as_deref() != Ok("1") {
                return;
            }
            let sequence = CAPABILITY_PROBE_SEQUENCE.fetch_add(1, Ordering::Relaxed);
            let pin_root = PathBuf::from(format!(
                "/sys/fs/bpf/opc-gtpu-historical-25-pristine-sibling-{}-{sequence}",
                std::process::id()
            ));
            struct ExactRootCleanup(PathBuf);
            impl Drop for ExactRootCleanup {
                fn drop(&mut self) {
                    let _ = fs::remove_dir_all(&self.0);
                }
            }
            let _cleanup = ExactRootCleanup(pin_root.clone());

            // This is the ordinary current-schema ownership constructor. It
            // creates exactly the current private root, tenant-A leaf, and
            // paired `<hash>-operation-v1` lock that a normal SDK owner uses.
            let current_a_pin = pin_root.join("tenant-a");
            let current_a = AyaGtpuRuntime::acquire_reconciler_ownership(&current_a_pin)
                .expect("create exact current tenant-A ownership on bpffs");
            let control_root = pin_root.join(RECONCILER_CONTROL_DIRECTORY);
            let current_a_leaf = control_root.join(&current_a.control_dir_name);
            let authority_marker =
                current_a_leaf.join(format!("SELECTOR_AUTHORITY_V1_{}", "ab".repeat(32)));
            fs::create_dir(&authority_marker).expect("create exact native authority marker");
            fs::set_permissions(&authority_marker, fs::Permissions::from_mode(0o700))
                .expect("preserve exact native authority-marker mode");
            let authority_marker_name = authority_marker
                .file_name()
                .and_then(|name| name.to_str())
                .expect("authority marker name is fixed ASCII");
            let current_a_lock = control_root.join(&current_a.operation_lock_name);
            assert!(current_a_leaf.is_dir());
            assert!(current_a_lock.is_dir());
            assert!(AyaGtpuRuntime::marker_inventory(
                &File::open(&current_a_leaf).expect("open current tenant-A leaf"),
            )
            .expect("tenant-A marker layout is exact")
            .0
            .iter()
            .any(|marker| marker == authority_marker_name));

            // The predecessor legitimately created both 0700 and 0755
            // namespace leaves, depending on the process umask. Their empty
            // shape is not authority for tenant B, but is still a conclusive
            // foreign predecessor residue that B must preserve. In
            // particular, the 0700 leaf also passes the native current
            // directory verifier, exercising the required legacy fallback.
            let foreign_legacy_0700 = control_root.join("11".repeat(32));
            fs::create_dir(&foreign_legacy_0700)
                .expect("create exact foreign predecessor 0700 leaf");
            fs::set_permissions(&foreign_legacy_0700, fs::Permissions::from_mode(0o700))
                .expect("preserve exact foreign predecessor 0700 mode");
            let foreign_legacy_0755 = control_root.join("22".repeat(32));
            fs::create_dir(&foreign_legacy_0755)
                .expect("create exact foreign predecessor 0755 leaf");
            fs::set_permissions(&foreign_legacy_0755, fs::Permissions::from_mode(0o755))
                .expect("preserve exact foreign predecessor 0755 mode");

            let before = AyaGtpuRuntime::historical_25_control_root_entries(
                &File::open(&control_root).expect("open shared current control root"),
                "ebpf_historical_25_pristine_sibling_before",
            )
            .expect("inventory exact shared current root");
            assert_eq!(before.len(), 4);
            assert!(before.contains(&current_a.control_dir_name));
            assert!(before.contains(&current_a.operation_lock_name));
            assert!(before.contains(&"11".repeat(32)));
            assert!(before.contains(&"22".repeat(32)));

            let target_b = pin_root.join("tenant-b");
            let replacement_ifindex =
                sys::ifindex_by_name("lo").expect("fresh netns loopback replacement identity");
            let outcome = AyaGtpuRuntime::historical_25_initialize_clean_absence(
                &target_b,
                ("lo", replacement_ifindex),
                50,
                super::super::test_historical_ebpf_graph_recovery_authority_binding(),
                &super::super::TestHistoricalEbpfGraphRecoveryCurrentness,
            )
            .expect("disjoint current namespace cannot make target-B absence ambiguous");
            assert_eq!(outcome, HistoricalEbpfGraphRecoveryOutcome::AlreadyAbsent);

            let after = AyaGtpuRuntime::historical_25_control_root_entries(
                &File::open(&control_root).expect("re-open shared current control root"),
                "ebpf_historical_25_pristine_sibling_after",
            )
            .expect("re-inventory shared current root");
            assert_eq!(after, before, "target-B pristine observation is read-only");
            assert!(foreign_legacy_0700.is_dir());
            assert!(foreign_legacy_0755.is_dir());
            assert!(!target_b.exists());
            assert!(!control_root
                .join(
                    AyaGtpuRuntime::historical_25_legacy_leaf_name(
                        target_b.file_name().expect("target B leaf")
                    )
                    .expect("derive target-B historical leaf"),
                )
                .exists());

            // A hash-shaped sibling is not sufficient. Once its bounded
            // predecessor inventory is malformed, the target observation is
            // no longer conclusive and must remain read-only/fail-closed.
            let malformed_legacy = control_root.join("33".repeat(32));
            fs::create_dir(&malformed_legacy)
                .expect("create hash-shaped malformed predecessor sibling");
            fs::set_permissions(&malformed_legacy, fs::Permissions::from_mode(0o700))
                .expect("preserve owner-only malformed sibling mode");
            fs::create_dir(malformed_legacy.join("unexpected"))
                .expect("add unclassified predecessor residue");
            assert!(matches!(
                AyaGtpuRuntime::historical_25_initialize_clean_absence(
                    &target_b,
                    ("lo", replacement_ifindex),
                    50,
                    super::super::test_historical_ebpf_graph_recovery_authority_binding(),
                    &super::super::TestHistoricalEbpfGraphRecoveryCurrentness,
                ),
                Err(GtpuError::StateIndeterminate {
                    operation: "ebpf_historical_25_pristine_absence"
                })
            ));
            assert!(
                !target_b.exists(),
                "malformed sibling cannot create target state"
            );
            drop(current_a);
            println!("OPC_GTPU_HISTORICAL_25_PRISTINE_SIBLING_PROVEN");
        }

        /// The foreign predecessor exception also covers an exact R5
        /// Qualified proof, rather than only the empty pre-R5 leaf.  It is a
        /// real bpffs/BPF-map fixture because a regular file can never stand
        /// in for the fixed ABI proof map that the classifier authenticates.
        #[test]
        #[ignore = "requires CAP_BPF, writable bpffs, an uncontended loopback tc view, and a fresh netns"]
        fn historical_25_pristine_absence_preserves_disjoint_qualified_legacy_proof_on_bpffs() {
            use std::os::unix::fs::{MetadataExt, PermissionsExt};

            if std::env::var("OPC_GTPU_RUN_PRIVILEGED").as_deref() != Ok("1") {
                return;
            }
            let sequence = CAPABILITY_PROBE_SEQUENCE.fetch_add(1, Ordering::Relaxed);
            let pin_root = PathBuf::from(format!(
                "/sys/fs/bpf/opc-gtpu-historical-25-pristine-r5-sibling-{}-{sequence}",
                std::process::id()
            ));
            struct ExactRootCleanup(PathBuf);
            impl Drop for ExactRootCleanup {
                fn drop(&mut self) {
                    let _ = fs::remove_dir_all(&self.0);
                }
            }
            let _cleanup = ExactRootCleanup(pin_root.clone());

            // Construct an independently valid current namespace first so
            // the shared root has the exact current-private ownership shape.
            let foreign_current_pin = pin_root.join("tenant-a-current");
            let foreign_current =
                AyaGtpuRuntime::acquire_reconciler_ownership(&foreign_current_pin)
                    .expect("create exact foreign current ownership");
            let control_root = pin_root.join(RECONCILER_CONTROL_DIRECTORY);
            let foreign_current_leaf = control_root.join(&foreign_current.control_dir_name);
            let authority_marker =
                foreign_current_leaf.join(format!("SELECTOR_AUTHORITY_V1_{}", "cd".repeat(32)));
            fs::create_dir(&authority_marker)
                .expect("create exact foreign current authority marker");
            fs::set_permissions(&authority_marker, fs::Permissions::from_mode(0o700))
                .expect("set exact foreign current authority-marker mode");

            let foreign_legacy = control_root.join("44".repeat(32));
            fs::create_dir(&foreign_legacy).expect("create exact foreign legacy proof leaf");
            fs::set_permissions(&foreign_legacy, fs::Permissions::from_mode(0o700))
                .expect("set exact foreign legacy leaf mode");
            let legacy_metadata = fs::metadata(&foreign_legacy).expect("foreign legacy identity");
            let mut proof_map =
                Array::<MapData, [u8; HISTORICAL_25_RECOVERY_PROOF_LEN]>::create(1, 0)
                    .expect("create fixed-width foreign R5 proof map");
            let map_ids = std::array::from_fn(|index| {
                u32::MAX
                    .checked_sub(u32::try_from(index).expect("bounded map index"))
                    .expect("map id remains nonzero")
            });
            let record = Historical25RecoveryRecord::unbound(
                super::super::test_historical_ebpf_graph_recovery_authority_binding(),
                [0x51; 32],
                [0x52; 16],
                (legacy_metadata.dev(), legacy_metadata.ino()),
                (0, 0),
                (
                    historical_25_replacement_name_commitment("foreign-up0")
                        .expect("canonical foreign replacement name"),
                    77,
                    50,
                ),
                ((2, 3), (4, 5)),
                map_ids,
            )
            .bind_to_proof_map(
                proof_map
                    .map()
                    .info()
                    .expect("foreign proof map identity")
                    .id(),
            )
            .expect("bind exact foreign R5 proof record");
            proof_map
                .set(0, record.encode(), 0)
                .expect("write exact foreign R5 proof record");
            proof_map
                .pin(foreign_legacy.join(HISTORICAL_25_RECOVERY_PROOF_MAP))
                .expect("pin exact foreign R5 proof map");

            let target_b = pin_root.join("tenant-b");
            let replacement_ifindex =
                sys::ifindex_by_name("lo").expect("fresh netns loopback replacement identity");
            assert_eq!(
                AyaGtpuRuntime::historical_25_initialize_clean_absence(
                    &target_b,
                    ("lo", replacement_ifindex),
                    50,
                    super::super::test_historical_ebpf_graph_recovery_authority_binding(),
                    &super::super::TestHistoricalEbpfGraphRecoveryCurrentness,
                )
                .expect("exact foreign Qualified R5 proof is disjoint from target B"),
                HistoricalEbpfGraphRecoveryOutcome::AlreadyAbsent
            );
            assert!(foreign_legacy
                .join(HISTORICAL_25_RECOVERY_PROOF_MAP)
                .exists());
            assert!(!target_b.exists());
            drop(foreign_current);
            println!("OPC_GTPU_HISTORICAL_25_PRISTINE_R5_SIBLING_PROVEN");
        }

        #[test]
        fn historical_25_recovery_record_seals_authority_graph_and_detached_state() {
            let map_ids = std::array::from_fn(|index| u32::try_from(index + 1).unwrap());
            let mut unbound = Historical25RecoveryRecord::unbound(
                super::super::test_historical_ebpf_graph_recovery_authority_binding(),
                [0x11; 32],
                [0x12; 16],
                (2, 3),
                (6, 7),
                (
                    historical_25_replacement_name_commitment("up0").unwrap(),
                    7,
                    50,
                ),
                ((0, 0), (0, 0)),
                map_ids,
            );
            // The external provenance challenge is SDK-computed from this
            // exact graph/map-ID tuple. A caller cannot choose a convenient
            // opaque value and make a same-shape graph resumable.
            unbound.external_graph_commitment = unbound.graph_commitment;
            let exact_unbound_graph =
                crate::HistoricalEbpfGraphRecoveryCommitment::new(unbound.graph_commitment)
                    .expect("derived graph challenge is nonzero");
            unbound.former_link_evidence =
                crate::HistoricalEbpfGraphRecoveryGraphInspection::exact_shipped_25(
                    exact_unbound_graph,
                )
                .former_link_evidence()
                .commitment()
                .bytes();
            assert_eq!(Historical25RecoveryRecord::decode(&unbound.encode()), None);
            let record = unbound.bind_to_proof_map(301).unwrap();
            let encoded = record.encode();
            assert_eq!(Historical25RecoveryRecord::decode(&encoded), Some(record));
            let mut forged_detached_token = record;
            forged_detached_token.former_link_evidence[0] ^= 1;
            assert_eq!(
                Historical25RecoveryRecord::decode(&forged_detached_token.encode()),
                None,
                "a checksum-valid caller-chosen former-link value cannot make a detached graph eligible"
            );
            assert_eq!(
                record.compatibility_contract_digest,
                crate::historical_ebpf_recovery_compatibility_kat([0; 32])
                    .compatibility_contract_digest()
                    .as_bytes(),
                "durable R5 proof state must bind the same public KAT/ABI contract as its receipt"
            );
            let authority =
                |scope, predecessor_basis, epoch, operation, host, root, leaf, observed_graph| {
                    let commitment = |byte| {
                        crate::HistoricalEbpfGraphRecoveryCommitment::new([byte; 32]).unwrap()
                    };
                    let inspection =
                        crate::HistoricalEbpfGraphRecoveryGraphInspection::exact_shipped_25(
                            observed_graph,
                        );
                    crate::HistoricalEbpfGraphRecoveryAuthority::new(
                        commitment(scope),
                        commitment(predecessor_basis),
                        commitment(0x88),
                        inspection.expected_challenge(),
                        std::num::NonZeroU64::new(epoch).unwrap(),
                        crate::HistoricalEbpfGraphRecoveryOperationId::new([operation; 16])
                            .unwrap(),
                        crate::HistoricalEbpfGraphRecoveryHostCommitments::new(
                            commitment(host),
                            commitment(root),
                            commitment(leaf),
                        ),
                        Box::new(super::super::TestHistoricalEbpfGraphRecoveryAuthorityGuard),
                    )
                    .binding()
                };
            let exact_record_graph =
                crate::HistoricalEbpfGraphRecoveryCommitment::new(record.graph_commitment)
                    .expect("derived graph challenge is nonzero");
            assert!(record.matches_authority(authority(
                0x81,
                0x82,
                1,
                0x83,
                0x84,
                0x85,
                0x86,
                exact_record_graph,
            )));
            for mismatched_authority in [
                authority(0x91, 0x82, 1, 0x83, 0x84, 0x85, 0x86, exact_record_graph),
                authority(0x81, 0x92, 1, 0x83, 0x84, 0x85, 0x86, exact_record_graph),
                authority(0x81, 0x82, 2, 0x83, 0x84, 0x85, 0x86, exact_record_graph),
                authority(0x81, 0x82, 1, 0x93, 0x84, 0x85, 0x86, exact_record_graph),
                authority(0x81, 0x82, 1, 0x83, 0x84, 0x95, 0x86, exact_record_graph),
                authority(0x81, 0x82, 1, 0x83, 0x84, 0x85, 0x96, exact_record_graph),
                authority(
                    0x81,
                    0x82,
                    1,
                    0x83,
                    0x84,
                    0x85,
                    0x86,
                    crate::HistoricalEbpfGraphRecoveryCommitment::new([0x90; 32])
                        .expect("nonzero wrong challenge"),
                ),
            ] {
                assert!(
                    !record.matches_authority(mismatched_authority),
                    "an R5 record must not resume under a different bound authority"
                );
            }
            let mut r4 = [0_u8; HISTORICAL_25_R4_RECOVERY_PROOF_LEN];
            r4.copy_from_slice(&encoded[..HISTORICAL_25_R4_RECOVERY_PROOF_LEN]);
            r4[..8].copy_from_slice(&HISTORICAL_25_R4_RECOVERY_MAGIC);
            r4[HISTORICAL_25_RECOVERY_REMOVAL_CURSOR_OFFSET
                ..HISTORICAL_25_RECOVERY_UPLINK_PROGRAM_ID_OFFSET]
                .fill(0);
            let r4_checksum = teardown_record_checksum(&r4[..HISTORICAL_25_R4_CHECKSUM_OFFSET]);
            r4[HISTORICAL_25_R4_CHECKSUM_OFFSET..].copy_from_slice(&r4_checksum.to_ne_bytes());
            assert_eq!(
                historical_25_decode_unbound_r4(&r4),
                Some(Historical25UnboundR4Receipt {
                    proof_map_id: record.proof_map_id,
                    legacy_control_device: record.legacy_control_device,
                    legacy_control_inode: record.legacy_control_inode,
                }),
                "R4 remains an observable but unbound predecessor record"
            );
            r4[HISTORICAL_25_RECOVERY_NAMESPACE_OFFSET] ^= 1;
            assert_eq!(
                historical_25_decode_unbound_r4(&r4),
                None,
                "an R4 observation remains checksum-sealed and cannot become authority"
            );
            for offset in [
                HISTORICAL_25_RECOVERY_NAMESPACE_OFFSET,
                HISTORICAL_25_RECOVERY_REPLACEMENT_NAME_OFFSET,
                HISTORICAL_25_RECOVERY_LEGACY_DEVICE_OFFSET,
                HISTORICAL_25_RECOVERY_CURRENT_CONTROL_INODE_OFFSET,
                HISTORICAL_25_RECOVERY_GRAPH_INODE_OFFSET,
                HISTORICAL_25_RECOVERY_UPLINK_PROGRAM_TAG_OFFSET,
                HISTORICAL_25_RECOVERY_MAP_IDS_OFFSET,
                HISTORICAL_25_RECOVERY_COMPATIBILITY_DIGEST_OFFSET,
                HISTORICAL_25_RECOVERY_GENERATION_OFFSET,
                HISTORICAL_25_RECOVERY_PRIOR_EPOCH_OFFSET,
                HISTORICAL_25_RECOVERY_PRIOR_OPERATION_OFFSET,
                HISTORICAL_25_RECOVERY_PRIOR_HOST_OFFSET,
                HISTORICAL_25_RECOVERY_PRIOR_ROOT_OFFSET,
                HISTORICAL_25_RECOVERY_PRIOR_LEAF_OFFSET,
            ] {
                let mut tampered = encoded;
                tampered[offset] ^= 1;
                assert_eq!(Historical25RecoveryRecord::decode(&tampered), None);
            }
            let mut incompatible_contract = encoded;
            incompatible_contract[HISTORICAL_25_RECOVERY_COMPATIBILITY_DIGEST_OFFSET
                ..HISTORICAL_25_RECOVERY_GENERATION_OFFSET]
                .fill(0x5a);
            let checksum = teardown_record_checksum(
                &incompatible_contract[..HISTORICAL_25_RECOVERY_CHECKSUM_OFFSET],
            );
            incompatible_contract[HISTORICAL_25_RECOVERY_CHECKSUM_OFFSET..]
                .copy_from_slice(&checksum.to_ne_bytes());
            assert_eq!(
                Historical25RecoveryRecord::decode(&incompatible_contract),
                None,
                "a checksum-valid R5 record for another KAT/ABI contract cannot resume or transfer"
            );
            let mut noncanonical_reserved_bytes = encoded;
            noncanonical_reserved_bytes[HISTORICAL_25_RECOVERY_TC_PRIORITY_OFFSET + 2] = 1;
            let checksum = teardown_record_checksum(
                &noncanonical_reserved_bytes[..HISTORICAL_25_RECOVERY_CHECKSUM_OFFSET],
            );
            noncanonical_reserved_bytes[HISTORICAL_25_RECOVERY_CHECKSUM_OFFSET..]
                .copy_from_slice(&checksum.to_ne_bytes());
            assert_eq!(
                Historical25RecoveryRecord::decode(&noncanonical_reserved_bytes),
                None,
                "reserved bytes must stay canonical even with a recomputed checksum"
            );
            let mut duplicate_map = record;
            duplicate_map.map_ids[1] = duplicate_map.map_ids[0];
            assert_eq!(
                Historical25RecoveryRecord::decode(&duplicate_map.encode()),
                None
            );
            let mut proof_aliases_graph_map = record;
            proof_aliases_graph_map.proof_map_id = proof_aliases_graph_map.map_ids[0];
            assert_eq!(
                Historical25RecoveryRecord::decode(&proof_aliases_graph_map.encode()),
                None
            );
            let mut attached_qualified = record;
            attached_qualified.uplink_program_id = 101;
            attached_qualified.downlink_program_id = 102;
            attached_qualified.uplink_program_tag = 0x0102_0304_0506_0708;
            attached_qualified.downlink_program_tag = 0x1112_1314_1516_1718;
            attached_qualified.graph_commitment = historical_25_graph_commitment(
                attached_qualified.namespace_hash,
                (
                    attached_qualified.graph_device,
                    attached_qualified.graph_inode,
                ),
                (
                    attached_qualified.replacement_name_hash,
                    attached_qualified.ifindex,
                    attached_qualified.tc_priority,
                ),
                (
                    (
                        attached_qualified.uplink_program_id,
                        attached_qualified.uplink_program_tag,
                    ),
                    (
                        attached_qualified.downlink_program_id,
                        attached_qualified.downlink_program_tag,
                    ),
                ),
                attached_qualified.map_ids,
            );
            attached_qualified.external_graph_commitment = attached_qualified.graph_commitment;
            let attached_receipt = Historical25AttachedCommittedReceipt {
                record: attached_qualified,
            };
            assert_eq!(
                Historical25RecoveryRecord::decode_observation(&attached_qualified.encode()),
                Some(Historical25RecoveryRecordObservation::AttachedCommitted(
                    attached_receipt
                )),
                "a canonical predecessor receipt must remain observable without becoming an effect proof"
            );
            assert_eq!(
                Historical25RecoveryRecord::decode(&attached_qualified.encode()),
                None,
                "qualified authority must never authorize detaching an active graph"
            );
            let installed_attached = attached_qualified.install_current((20, 21)).unwrap();
            assert_eq!(
                Historical25RecoveryRecord::decode_observation(&installed_attached.encode()),
                Some(Historical25RecoveryRecordObservation::AttachedCommitted(
                    Historical25AttachedCommittedReceipt {
                        record: installed_attached,
                    }
                )),
                "a committed predecessor receipt must be classified after restart"
            );
            assert_eq!(
                Historical25RecoveryRecord::decode(&installed_attached.encode()),
                None,
                "an older attached installed receipt must resume fail-closed"
            );
            let mut aliased_program_identity = installed_attached;
            aliased_program_identity.downlink_program_id =
                aliased_program_identity.uplink_program_id;
            assert_eq!(
                Historical25RecoveryRecord::decode_observation(&aliased_program_identity.encode()),
                None,
                "the predecessor never authenticated one program ID as both hooks"
            );
            let mut attached_graph_absent = installed_attached;
            attached_graph_absent.phase = Historical25RecoveryPhase::GraphAbsent;
            assert_eq!(
                Historical25RecoveryRecord::decode(&attached_graph_absent.encode()),
                None,
                "graph-absent authority must encode a detached graph"
            );
            assert_eq!(
                Historical25RecoveryRecord::decode_observation(&attached_graph_absent.encode()),
                None,
                "an attached terminal-phase receipt is malformed, not resumable"
            );

            let mut detached = Historical25RecoveryRecord::unbound(
                super::super::test_historical_ebpf_graph_recovery_authority_binding(),
                [0x22; 32],
                [0x23; 16],
                (12, 13),
                (16, 17),
                (
                    historical_25_replacement_name_commitment("up0").unwrap(),
                    19,
                    50,
                ),
                ((0, 0), (0, 0)),
                map_ids,
            )
            .bind_to_proof_map(302)
            .unwrap();
            detached.external_graph_commitment = detached.graph_commitment;
            detached.former_link_evidence =
                crate::HistoricalEbpfGraphRecoveryGraphInspection::exact_shipped_25(
                    crate::HistoricalEbpfGraphRecoveryCommitment::new(detached.graph_commitment)
                        .expect("derived graph challenge is nonzero"),
                )
                .former_link_evidence()
                .commitment()
                .bytes();
            assert_eq!(
                Historical25RecoveryRecord::decode(&detached.encode()),
                Some(detached)
            );
            let detached_installed = detached.install_current((22, 23)).unwrap();
            let detached_fully_removed = (0..PRE_SELECTOR_STAMP_TRAFFIC_OBSERVATION_V1_MAP_NAMES
                .len())
                .try_fold(detached_installed, |record, index| {
                    record
                        .prepare_pin_removal(index)
                        .and_then(|record| record.finish_pin_removal(index))
                })
                .expect("the test records the complete ordered 25-pin removal");
            let detached_terminal = detached_fully_removed
                .advance_phase(Historical25RecoveryPhase::GraphAbsent)
                .unwrap()
                .advance_phase(Historical25RecoveryPhase::Terminal)
                .unwrap();
            assert_eq!(
                Historical25RecoveryRecord::decode(&detached_terminal.encode()),
                Some(detached_terminal)
            );
            let terminal_graph =
                crate::HistoricalEbpfGraphRecoveryCommitment::new(historical_25_graph_commitment(
                    [0x61; 32],
                    (65, 66),
                    (
                        historical_25_replacement_name_commitment("up0").unwrap(),
                        19,
                        50,
                    ),
                    ((0, 0), (0, 0)),
                    map_ids,
                ))
                .expect("derived terminal graph challenge is nonzero");
            let old_terminal_authority =
                authority(0x41, 0x42, 7, 0x43, 0x44, 0x45, 0x46, terminal_graph);
            let new_terminal_authority =
                authority(0x51, 0x52, 8, 0x53, 0x44, 0x45, 0x46, terminal_graph);
            let terminal_installed_for_adoption = Historical25RecoveryRecord::unbound(
                old_terminal_authority,
                [0x61; 32],
                [0x62; 16],
                (63, 64),
                (65, 66),
                (
                    historical_25_replacement_name_commitment("up0").unwrap(),
                    19,
                    50,
                ),
                ((0, 0), (0, 0)),
                map_ids,
            )
            .bind_to_proof_map(304)
            .unwrap()
            .install_current((67, 68))
            .unwrap();
            let terminal_fully_removed_for_adoption = (0
                ..PRE_SELECTOR_STAMP_TRAFFIC_OBSERVATION_V1_MAP_NAMES.len())
                .try_fold(terminal_installed_for_adoption, |record, index| {
                    record
                        .prepare_pin_removal(index)
                        .and_then(|record| record.finish_pin_removal(index))
                })
                .expect("the test records the complete ordered 25-pin removal");
            let terminal_for_adoption = terminal_fully_removed_for_adoption
                .advance_phase(Historical25RecoveryPhase::GraphAbsent)
                .unwrap()
                .advance_phase(Historical25RecoveryPhase::Terminal)
                .unwrap();
            assert!(!terminal_for_adoption.matches_authority(new_terminal_authority));
            assert!(terminal_for_adoption.matches_authority_target(new_terminal_authority));
            let adopted_terminal = terminal_for_adoption
                .rebind_terminal_authority(new_terminal_authority)
                .expect("only exact terminal R5 may transfer to a new live scope");
            assert!(adopted_terminal.matches_authority(new_terminal_authority));
            assert_eq!(
                adopted_terminal.terminal_adoption(),
                Some(
                    crate::HistoricalEbpfGraphRecoveryTerminalAdoption::with_full_prior_authority(
                        old_terminal_authority,
                    ),
                ),
                "the transfer receipt records the complete immediately preceding authority"
            );
            assert_eq!(
                Historical25RecoveryRecord::decode(&adopted_terminal.encode()),
                Some(adopted_terminal),
                "the transfer provenance is checksummed with R5"
            );
            for wrong_target in [
                authority(0x51, 0x52, 8, 0x53, 0x54, 0x45, 0x46, terminal_graph),
                authority(0x51, 0x52, 8, 0x53, 0x44, 0x55, 0x46, terminal_graph),
                authority(0x51, 0x52, 8, 0x53, 0x44, 0x45, 0x56, terminal_graph),
            ] {
                assert!(
                    terminal_for_adoption
                        .rebind_terminal_authority(wrong_target)
                        .is_none(),
                    "a changed host/root/leaf must not adopt an old terminal R5 record"
                );
            }
            assert!(
                terminal_for_adoption
                    .advance_phase(Historical25RecoveryPhase::GraphAbsent)
                    .is_none(),
                "terminal phase cannot be rewound into an in-progress state"
            );
            let mut nonterminal_for_adoption = terminal_for_adoption;
            nonterminal_for_adoption.phase = Historical25RecoveryPhase::GraphAbsent;
            assert!(
                nonterminal_for_adoption
                    .rebind_terminal_authority(new_terminal_authority)
                    .is_none(),
                "a nonterminal R5 record never transfers to a changed scope"
            );
            let detached_installed = detached.install_current((22, 23)).unwrap();
            let detached_graph_absent = detached_fully_removed
                .advance_phase(Historical25RecoveryPhase::GraphAbsent)
                .unwrap();
            for phase in [
                detached,
                detached_installed,
                detached_graph_absent,
                detached_terminal,
            ] {
                assert!(phase.matches_replacement(("up0", 19), 50));
                assert!(
                    !phase.matches_replacement(("renamed0", 19), 50),
                    "same ifindex under a different name must never resume phase {:?}",
                    phase.phase
                );
                assert!(!phase.matches_replacement(("up0", 20), 50));
                assert!(!phase.matches_replacement(("up0", 19), 51));
            }
            let mut mixed_attachment = detached;
            mixed_attachment.uplink_program_id = 101;
            assert_eq!(
                Historical25RecoveryRecord::decode(&mixed_attachment.encode()),
                None
            );
            assert_eq!(
                Historical25RecoveryRecord::decode_observation(&mixed_attachment.encode()),
                None,
                "partial program identity must remain malformed"
            );
        }

        #[test]
        fn graph_absent_receipt_rejects_a_present_graph_before_any_effect() {
            assert!(
                AyaGtpuRuntime::historical_25_phase_is_consistent_with_graph_presence(
                    Historical25RecoveryPhase::Installed,
                    true,
                )
            );
            assert!(
                AyaGtpuRuntime::historical_25_phase_is_consistent_with_graph_presence(
                    Historical25RecoveryPhase::Installed,
                    false,
                )
            );
            assert!(
                AyaGtpuRuntime::historical_25_phase_is_consistent_with_graph_presence(
                    Historical25RecoveryPhase::GraphAbsent,
                    false,
                )
            );
            assert!(
                !AyaGtpuRuntime::historical_25_phase_is_consistent_with_graph_presence(
                    Historical25RecoveryPhase::GraphAbsent,
                    true,
                ),
                "committed graph-absence authority cannot coexist with a live graph"
            );
        }

        #[test]
        fn legacy_v2_teardown_record_rejects_tamper_and_inconsistent_hook_identity() {
            let identity = LegacyV2DatapathIdentity {
                uplink: LegacyV2ProgramIdentity {
                    tags: LegacyV2ProgramTags { sha1: 1, sha256: 2 },
                    map_ids: vec![1, 2, 3, 4, 7, 8, 9],
                },
                downlink: LegacyV2ProgramIdentity {
                    tags: LegacyV2ProgramTags { sha1: 3, sha256: 4 },
                    map_ids: vec![5, 6, 7, 8],
                },
                map_ids: [1, 2, 3, 4, 5, 6, 7, 8, 9],
            };
            let unbound =
                LegacyV2TeardownRecord::from_identity(7, 50, &identity, (101, 1), (102, 3));
            assert_eq!(LegacyV2TeardownRecord::decode(&unbound.encode()), None);
            let record = unbound.bind_to_proof_map(301).unwrap();
            let encoded = record.encode();
            assert_eq!(LegacyV2TeardownRecord::decode(&encoded), Some(record));

            let mut tampered = encoded;
            tampered[40] ^= 1;
            assert_eq!(LegacyV2TeardownRecord::decode(&tampered), None);

            let mut inconsistent = record;
            inconsistent.uplink_program_tag = 0;
            assert_eq!(LegacyV2TeardownRecord::decode(&inconsistent.encode()), None);

            let mut absent_hook = record;
            absent_hook.downlink_program_id = 0;
            absent_hook.downlink_program_tag = 0;
            assert_eq!(LegacyV2TeardownRecord::decode(&absent_hook.encode()), None);

            assert!(legacy_v2_proof_map_abi_is_exact(
                bpf_map_type::BPF_MAP_TYPE_ARRAY as u32,
                4,
                LEGACY_V2_TEARDOWN_PROOF_LEN as u32,
                1,
                0,
            ));
            for abi in [
                (
                    bpf_map_type::BPF_MAP_TYPE_HASH as u32,
                    4,
                    LEGACY_V2_TEARDOWN_PROOF_LEN as u32,
                    1,
                    0,
                ),
                (
                    bpf_map_type::BPF_MAP_TYPE_ARRAY as u32,
                    8,
                    LEGACY_V2_TEARDOWN_PROOF_LEN as u32,
                    1,
                    0,
                ),
                (
                    bpf_map_type::BPF_MAP_TYPE_ARRAY as u32,
                    4,
                    LEGACY_V2_TEARDOWN_PROOF_LEN as u32 + 1,
                    1,
                    0,
                ),
                (
                    bpf_map_type::BPF_MAP_TYPE_ARRAY as u32,
                    4,
                    LEGACY_V2_TEARDOWN_PROOF_LEN as u32,
                    2,
                    0,
                ),
                (
                    bpf_map_type::BPF_MAP_TYPE_ARRAY as u32,
                    4,
                    LEGACY_V2_TEARDOWN_PROOF_LEN as u32,
                    1,
                    1,
                ),
            ] {
                assert!(!legacy_v2_proof_map_abi_is_exact(
                    abi.0, abi.1, abi.2, abi.3, abi.4,
                ));
            }
            assert!(legacy_v2_proof_record_is_authoritative(
                record,
                301,
                identity.uplink.tags,
                identity.downlink.tags,
            ));
            assert!(!legacy_v2_proof_record_is_authoritative(
                record,
                302,
                identity.uplink.tags,
                identity.downlink.tags,
            ));
            assert!(!legacy_v2_proof_record_is_authoritative(
                record,
                301,
                LegacyV2ProgramTags {
                    sha1: 999,
                    sha256: 1_000,
                },
                identity.downlink.tags,
            ));
            assert!(!legacy_v2_proof_record_is_authoritative(
                record,
                301,
                identity.uplink.tags,
                LegacyV2ProgramTags {
                    sha1: 999,
                    sha256: 1_000,
                },
            ));
        }

        #[test]
        fn map_delete_treats_aya_enoent_as_an_idempotent_absence() {
            assert!(!map_delete_result("delete", Err(MapError::KeyNotFound)).unwrap());
            let absent = MapError::SyscallError(aya::sys::SyscallError {
                call: "bpf_map_delete_elem",
                io_error: io::Error::from(io::ErrorKind::NotFound),
            });
            assert!(!map_delete_result("delete", Err(absent)).unwrap());

            let denied = MapError::SyscallError(aya::sys::SyscallError {
                call: "bpf_map_delete_elem",
                io_error: io::Error::from(io::ErrorKind::PermissionDenied),
            });
            assert!(matches!(
                map_delete_result("delete", Err(denied)).unwrap_err(),
                GtpuError::Io {
                    operation: "delete",
                    kind: io::ErrorKind::Other,
                    ..
                }
            ));
        }

        fn hook(
            name: &'static str,
            attach_type: TcAttachType,
            program_id: u32,
        ) -> ProgramHook<'static> {
            ProgramHook {
                name,
                attach_type,
                program_id,
            }
        }

        #[test]
        fn failed_attach_ack_is_reconciled_from_each_exact_live_hook() {
            for hook in [
                hook(PROG_UPLINK, TcAttachType::Egress, 71),
                hook(PROG_DOWNLINK, TcAttachType::Ingress, 72),
            ] {
                let exact = Ok(Some(FilterOwner {
                    name: hook.name.into(),
                    program_id: Some(hook.program_id),
                }));
                assert_eq!(
                    classify_failed_attach_readback(SlotDisposition::Empty, hook, &exact),
                    FailedAttachReadback::AdoptExact
                );
                assert_eq!(
                    classify_failed_attach_readback(
                        SlotDisposition::ReplaceExact {
                            current_program_id: hook.program_id.saturating_sub(1),
                        },
                        hook,
                        &exact,
                    ),
                    FailedAttachReadback::AdoptExact
                );
            }
        }

        #[test]
        fn failed_atomic_replace_distinguishes_the_original_from_unknown_state() {
            let hook = hook(PROG_UPLINK, TcAttachType::Egress, 71);
            let slot = SlotDisposition::ReplaceExact {
                current_program_id: 70,
            };
            let original = Ok(Some(FilterOwner {
                name: hook.name.into(),
                program_id: Some(70),
            }));
            assert_eq!(
                classify_failed_attach_readback(slot, hook, &original),
                FailedAttachReadback::ProvenOriginal
            );

            for owner in [
                Ok(None),
                Ok(Some(FilterOwner {
                    name: hook.name.into(),
                    program_id: Some(69),
                })),
                Ok(Some(FilterOwner {
                    name: "external".into(),
                    program_id: Some(70),
                })),
            ] {
                assert_eq!(
                    classify_failed_attach_readback(slot, hook, &owner),
                    FailedAttachReadback::Indeterminate
                );
            }
        }

        #[test]
        fn failed_attach_is_ordinary_only_when_an_originally_empty_slot_is_proven_empty() {
            let hook = hook(PROG_UPLINK, TcAttachType::Egress, 71);
            let empty = Ok(None);
            assert_eq!(
                classify_failed_attach_readback(SlotDisposition::Empty, hook, &empty),
                FailedAttachReadback::ProvenAbsent
            );
            assert_eq!(
                classify_failed_attach_readback(
                    SlotDisposition::ReplaceExact {
                        current_program_id: 70,
                    },
                    hook,
                    &empty,
                ),
                FailedAttachReadback::Indeterminate
            );
            let foreign = Ok(Some(FilterOwner {
                name: "external".into(),
                program_id: Some(99),
            }));
            assert_eq!(
                classify_failed_attach_readback(SlotDisposition::Empty, hook, &foreign),
                FailedAttachReadback::Indeterminate
            );
            let unreadable = Err(GtpuError::io(
                "ebpf_tc_filter_dump",
                io::Error::other("injected"),
            ));
            assert_eq!(
                classify_failed_attach_readback(SlotDisposition::Empty, hook, &unreadable),
                FailedAttachReadback::Indeterminate
            );
        }

        #[test]
        fn mutation_ack_loss_and_failed_rollbacks_are_indeterminate() {
            assert!(matches!(
                mutation_or_indeterminate::<(), _>(Err(()), "ebpf_tc_replace"),
                Err(GtpuError::StateIndeterminate {
                    operation: "ebpf_tc_replace"
                })
            ));
            for source in ["second_hook", "schema_marker", "devices_lock"] {
                let error = error_after_rollback(
                    GtpuError::io(source, io::Error::other("injected source")),
                    Err(GtpuError::io(
                        "ebpf_tc_attach_rollback",
                        io::Error::other("injected rollback"),
                    )),
                    false,
                    "ebpf_tc_attach_rollback",
                );
                assert!(matches!(
                    error,
                    GtpuError::StateIndeterminate {
                        operation: "ebpf_tc_attach_rollback"
                    }
                ));
            }
            let source = error_after_rollback(
                GtpuError::AlreadyExists,
                Ok(()),
                false,
                "ebpf_tc_attach_rollback",
            );
            assert!(matches!(source, GtpuError::AlreadyExists));
            let replaced_source = error_after_rollback(
                GtpuError::AlreadyExists,
                Ok(()),
                true,
                "ebpf_tc_attach_rollback",
            );
            assert!(matches!(
                replaced_source,
                GtpuError::StateIndeterminate {
                    operation: "ebpf_tc_attach_rollback"
                }
            ));
        }

