        #[test]
        fn fresh_cleanup_rejects_swapped_named_pin_paths() {
            let expected = PinnedMapIdentity {
                uplink_far: 1,
                uplink_mark_far: 2,
                uplink_dscp: 3,
                uplink_mark_dscp: 4,
                uplink_source_port: 12,
                uplink_mark_source_port: 13,
                uplink_pmtu: 14,
                uplink_pmtu_counters: 15,
                downlink_pdr: 5,
                downlink_mark_pdr: 6,
                downlink_binding: 7,
                marked_owner: 8,
                counters: 9,
                downlink_binding_counters: 10,
                config: 11,
                session_groups: 16,
                session_uplink_index: 17,
                session_downlink_index: 18,
                session_transactions: 19,
                session_selector_stamps: 34,
                config_ipv6: 20,
                session_schema: 21,
                tft_schema: 22,
                tft_meta: 23,
                tft_filters: 24,
                tft_counters: 25,
                traffic_observation_registration: 26,
                traffic_observation_redirect: 33,
                traffic_observation_events: 27,
                traffic_observation_loss: 28,
                traffic_observation_sequence: 29,
                traffic_observation_gate: 30,
                traffic_observation_sequence_lock: 31,
                traffic_observation_flow_scratch: 32,
            };
            let swapped = PinnedMapIdentity {
                uplink_far: expected.uplink_dscp,
                uplink_dscp: expected.uplink_far,
                ..expected.clone()
            };

            assert_ne!(swapped, expected);
            assert!(pin_cleanup_preflight_matches(
                Some(&expected),
                Some(&expected),
                true,
            ));
            assert!(!pin_cleanup_preflight_matches(
                Some(&expected),
                Some(&swapped),
                true,
            ));
            assert!(!pin_cleanup_preflight_matches(
                Some(&expected),
                Some(&expected),
                false,
            ));
            assert!(pin_cleanup_preflight_matches(None, None, true));
            assert!(!pin_cleanup_preflight_matches(None, None, false));
        }

