        fn traffic_observation_drain(
            &self,
            ifindex: u32,
            budget: usize,
        ) -> Result<EbpfTrafficObservationDrain, GtpuError> {
            let mut state = self.state();
            state.operations.push("traffic_observation_drain");
            Self::fail_if_requested(&mut state, "traffic_observation_drain")?;
            if !state.grouped_map_ready.contains(&ifindex) || budget == 0 {
                return Err(GtpuError::NotFound);
            }
            let queue = state.traffic_observation_events.entry(ifindex).or_default();
            let mut records = Vec::with_capacity(budget);
            while records.len() < budget {
                let Some(record) = queue.pop_front() else {
                    break;
                };
                records.push(record);
            }
            Ok(EbpfTrafficObservationDrain {
                records,
                overflowed: !queue.is_empty(),
            })
        }

        fn traffic_observation_loss(&self, ifindex: u32) -> Result<u64, GtpuError> {
            let mut state = self.state();
            state.operations.push("traffic_observation_loss");
            Self::fail_if_requested(&mut state, "traffic_observation_loss")?;
            if let Some(remaining) = state.traffic_observation_loss_fail_on_read.as_mut() {
                if *remaining == 0 {
                    state.traffic_observation_loss_fail_on_read = None;
                    return Err(GtpuError::io(
                        "traffic_observation_loss",
                        io::Error::other("injected fake runtime failure"),
                    ));
                }
                *remaining -= 1;
            }
            if !state.grouped_map_ready.contains(&ifindex) {
                return Err(GtpuError::NotFound);
            }
            Ok(state
                .traffic_observation_loss
                .get(&ifindex)
                .copied()
                .unwrap_or(0))
        }

        fn datapath_snapshot(&self, ifindex: u32) -> Result<EbpfGtpuDatapathSnapshot, GtpuError> {
            let mut state = self.state();
            let exact = state.attached.contains_key(&ifindex)
                && state.dscp_map_ready.contains(&ifindex)
                && state.marked_far_map_ready.contains(&ifindex)
                && state.marked_dscp_map_ready.contains(&ifindex)
                && state.sport_map_ready.contains(&ifindex)
                && state.marked_sport_map_ready.contains(&ifindex)
                && state.pmtu_map_ready.contains(&ifindex)
                && state.pmtu_counters_map_ready.contains(&ifindex)
                && state.marked_pdr_map_ready.contains(&ifindex)
                && state.marked_owner_map_ready.contains(&ifindex)
                && state.downlink_binding_map_ready.contains(&ifindex)
                && state.downlink_binding_counters_map_ready.contains(&ifindex)
                && state.uplink_filter_ready.contains(&ifindex)
                && state.downlink_filter_ready.contains(&ifindex)
                && !state.pin_identity_invalid.contains(&ifindex)
                && !state.uplink_filter_foreign.contains(&ifindex)
                && !state.downlink_filter_foreign.contains(&ifindex);
            if !exact {
                return Err(GtpuError::StateIndeterminate {
                    operation: "ebpf_datapath_snapshot",
                });
            }
            state.operations.push("datapath_snapshot");
            Ok(state.datapath_snapshot)
        }

        fn pmtu_policy_get(&self, ifindex: u32) -> Result<[u8; UPLINK_PMTU_VALUE_LEN], GtpuError> {
            let state = self.state();
            if !state.pmtu_map_ready.contains(&ifindex) {
                return Err(GtpuError::io(
                    "ebpf_pmtu_map",
                    io::Error::new(io::ErrorKind::NotFound, "MTU policy map unavailable"),
                ));
            }
            Ok(state.pmtu_policy.get(&ifindex).copied().unwrap_or([0; 4]))
        }

        fn pmtu_policy_write(
            &self,
            ifindex: u32,
            value: [u8; UPLINK_PMTU_VALUE_LEN],
        ) -> Result<(), GtpuError> {
            self.pmtu_policy_write_graph_locked(ifindex, value, false)
        }

        fn pmtu_policy_write_graph_locked(
            &self,
            ifindex: u32,
            value: [u8; UPLINK_PMTU_VALUE_LEN],
            allow_raw_pmtu_repair: bool,
        ) -> Result<(), GtpuError> {
            if !ebpf_pmtu_map_state_is_executable(GtpuUplinkMtuPolicy::decode_map_value(&value)) {
                return Err(GtpuError::invalid_config(
                    "device.uplink_mtu_policy",
                    "non-canonical MTU policy bytes",
                ));
            }
            let mut guard = self.acquire_selector_namespace_effect_guard(ifindex, None)?;
            {
                let mut state = self.state();
                if !allow_raw_pmtu_repair
                    && state.pmtu_policy.get(&ifindex).is_some_and(|policy| {
                        !ebpf_pmtu_map_state_is_executable(GtpuUplinkMtuPolicy::decode_map_value(
                            policy,
                        ))
                    })
                {
                    return Err(state_indeterminate("ebpf_pmtu_policy_update"));
                }
                if !state.pmtu_map_ready.contains(&ifindex) {
                    return Err(GtpuError::StateIndeterminate {
                        operation: "ebpf_pmtu_policy_update",
                    });
                }
                let mut expected = FakeSelectorNamespaceGraphIdentity::capture(&state, ifindex);
                expected.pmtu_policy = value;
                guard.graph = Some(expected);
                state.operations.push("pmtu_policy_write");
                Self::fail_if_requested(&mut state, "pmtu_policy_write")?;
                state.pmtu_policy.insert(ifindex, value);
                if state.pmtu_policy.get(&ifindex).copied() != Some(value) {
                    return Err(GtpuError::StateIndeterminate {
                        operation: "ebpf_pmtu_policy_update",
                    });
                }
            }
            Box::new(guard).finish()
        }

