    #[tokio::test]
    async fn historical_25_successor_keeps_authority_until_backend_registration() {
        use crate::CurrentEbpfGraphRecoveryTerminalAdmissionOutcome as Admission;

        let (backend, runtime) = backend_with_fake();
        let pin_namespace = "s2bu-new";
        let pin_dir = PathBuf::from(DEFAULT_BPFFS_PIN_ROOT).join(pin_namespace);
        {
            let mut state = runtime.state();
            state
                .historical_25_graphs
                .insert(pin_dir.clone(), FakeHistorical25Graph::default());
            state.historical_25_legacy_leaves.insert(pin_dir.clone());
            state.historical_25_control_root_mode =
                FakeHistorical25ControlRootMode::Predecessor0755;
        }

        let historical = historical_25_recovery_request_for_namespace_with_authority(
            pin_namespace,
            "s2bu-new",
            REPLACEMENT_IFINDEX,
            historical_25_authority(),
        );
        assert_eq!(
            backend
                .recover_orphaned_historical_ebpf_graph(historical)
                .await
                .expect("retire the exact detached shipped-25 graph"),
            crate::HistoricalEbpfGraphRecoveryOutcome::Removed
        );

        let current_intent = || {
            crate::CurrentEbpfGraphRecoveryIntent::new(
                pin_namespace,
                crate::CurrentEbpfGraphWriterProof::previous_writer_stopped(),
            )
            .with_replacement_device(GtpDevice {
                name: "s2bu-new".to_string(),
                ifindex: REPLACEMENT_IFINDEX,
            })
            .with_drain_proof(crate::CurrentEbpfGraphDrainProof::sessions_and_traffic_drained())
        };
        let terminal = backend
            .recover_orphaned_current_ebpf_graph_with_authority_receipt(
                current_intent().into_request_with_authority(current_recovery_authority()),
            )
            .await
            .expect("publish the authenticated R5-source current terminal");
        assert_eq!(
            backend
                .admit_current_ebpf_graph_terminal(
                    current_intent()
                        .into_terminal_admission_request(terminal, current_recovery_authority()),
                )
                .await
                .expect("admit the exact broker-durable terminal"),
            Admission::Admitted
        );

        runtime.fail_in_order(["pmtu_policy_write"]);
        let mut request = CreateGtpDeviceRequest::new("s2bu-new");
        request.bind_address = IpAddr::V4(Ipv4Addr::new(192, 0, 2, 1));
        request.uplink_mtu_policy = Some(
            GtpuUplinkMtuPolicy::new(1280, crate::GtpuOuterFragmentPolicy::SignalPacketTooBig)
                .expect("test PMTU policy is canonical"),
        );
        assert!(matches!(
            backend.create_device(request).await,
            Err(GtpuError::Io {
                operation: "pmtu_policy_write",
                ..
            }) | Err(GtpuError::StateIndeterminate { .. })
        ));

        let state = runtime.state();
        assert!(
            state
                .current_recovery_terminal_leaves
                .contains_key(&pin_dir),
            "a post-attach failure must retain the authenticated predecessor WAL"
        );
        assert!(
            state.current_recovery_authority_leaves.contains(&pin_dir),
            "the successor remains recoverable only while its durable authority pin survives"
        );
        assert!(
            state.historical_25_receipts.contains_key(&pin_dir)
                && state.historical_25_authorities.contains_key(&pin_dir)
                && state.historical_25_operation_markers.contains(&pin_dir),
            "ordinary attach cannot retire the R5 handoff before backend registration"
        );
    }

    #[test]
    fn successor_traffic_gate_is_the_first_tc_packet_effect_boundary() {
        // This test reads the committed eBPF source from the host test crate,
        // where it is executable in CI even though the standalone datapath
        // crate targets `bpfel-unknown-none`. The build script below compiles
        // that same source into the committed runtime object.
        let source = include_str!("../../opc-gtpu-dataplane-ebpf/src/main.rs");
        for (classifier, terminator, first_packet_read) in [
            (
                "pub fn opc_gtpu_uplink(mut ctx: TcContext)",
                "#[classifier]\npub fn opc_gtpu_downlink",
                "let mark = packet_mark(&ctx);",
            ),
            (
                "pub fn opc_gtpu_downlink(mut ctx: TcContext)",
                "/// Uplink: inner IPv4 packet",
                "let Ok(ether_type) = ctx.load::<u16>(12)",
            ),
        ] {
            let (_, root) = source
                .split_once(format!("#[classifier]\n{classifier}").as_str())
                .expect("tc classifier root is present");
            let (root, _) = root
                .split_once(terminator)
                .expect("tc classifier root has a bounded body");
            let gate_start = root
                .find("if !traffic_gate_allows_packet_effects()")
                .expect("classifier has a traffic-inert gate");
            let first_effect = root
                .find(first_packet_read)
                .expect("packet-processing body is present");
            assert!(gate_start < first_effect);
            let gate = &root[gate_start..first_effect];
            assert!(gate.contains("return TC_ACT_OK;"));
            assert!(!gate.contains("bpf_redirect"));
            assert!(!gate.contains("TC_ACT_SHOT"));
            assert!(!gate.contains("bpf_skb_"));
        }
    }

    #[test]
    fn fresh_grouped_config_write_is_inside_the_successor_effect_guard() {
        // Aya maps cannot be exercised without kernel capabilities in this
        // unit-test target. Keep the source-level boundary explicit: the
        // fresh branch is as authority-guarded as grouped replacement writes.
        let source = include_str!("ebpf.rs");
        let (_, aya_runtime) = source
            .split_once("impl EbpfGtpuRuntime for AyaGtpuRuntime {")
            .expect("Aya runtime implementation is present");
        let (_, grouped_attach) = aya_runtime
            .split_once("fn attach_grouped(")
            .expect("Aya grouped attach is present");
        let (grouped_attach, _) = grouped_attach
            .split_once("fn finalize_current_terminal_successor(")
            .expect("Aya grouped attach has a bounded body");
        assert!(grouped_attach.contains(
            "None => Self::with_current_terminal_successor_effect(\n                        terminal_admission.as_ref(),\n                        \"ebpf_current_successor_grouped_config\","
        ));
    }

    #[tokio::test]
    async fn historical_25_sealed_successor_is_fenced_until_same_process_broker_admission() {
        use crate::CurrentEbpfGraphRecoverySuccessorAdmissionOutcome as Outcome;

        let (backend, runtime, receipt) = sealed_historical_25_successor().await;
        let pin_dir = PathBuf::from(DEFAULT_BPFFS_PIN_ROOT).join("up0");
        assert!(
            runtime
                .state()
                .successor_datapath_inert
                .contains(&REPLACEMENT_IFINDEX),
            "the pre-admission tc graph is packet-inert"
        );
        assert!(matches!(
            backend.resolve_device("up0").await,
            Err(GtpuError::StateIndeterminate {
                operation: "ebpf_current_terminal_successor_pending"
            })
        ));
        assert_eq!(
            backend
                .admit_current_ebpf_graph_successor(
                    historical_25_successor_intent().into_successor_admission_request(
                        historical_25_successor_target(),
                        receipt,
                        current_recovery_authority_for_successor_receipt(receipt),
                    ),
                )
                .await
                .expect("same process admits only its exact brokered successor"),
            Outcome::Admitted
        );
        assert_eq!(
            backend
                .resolve_device("up0")
                .await
                .expect("ordinary runtime becomes usable after broker admission")
                .ifindex,
            REPLACEMENT_IFINDEX
        );
        let state = runtime.state();
        assert!(!state.successor_pending.contains(&REPLACEMENT_IFINDEX));
        assert!(
            !state
                .successor_datapath_inert
                .contains(&REPLACEMENT_IFINDEX),
            "the exact same-process broker admission is the activation cut"
        );
        assert!(!state
            .current_recovery_successor_main_leaves
            .contains_key(&pin_dir));
        assert!(!state
            .current_recovery_terminal_leaves
            .contains_key(&pin_dir));
        assert!(!state.current_recovery_authority_leaves.contains(&pin_dir));
        assert!(state.historical_25_receipts.contains_key(&pin_dir));
        assert!(state.historical_25_authorities.contains_key(&pin_dir));
        assert!(state.historical_25_operation_markers.contains(&pin_dir));
    }

    #[tokio::test]
    async fn activation_revocation_after_odd_gate_write_restores_exact_even_and_retry_converges() {
        let (_, runtime, _) = sealed_historical_25_successor().await;
        let pin_dir = PathBuf::from(DEFAULT_BPFFS_PIN_ROOT).join("up0");
        let disabled_gate = runtime.state().traffic_observation_gate[&REPLACEMENT_IFINDEX];
        let resets_before = runtime
            .state()
            .operations
            .iter()
            .filter(|operation| **operation == "traffic_observation_reset")
            .count();
        assert_ne!(disabled_gate, 0);
        assert_eq!(disabled_gate & 1, 0);
        // The first two checks are pre-write; the third runs after the fake
        // odd gate write and revokes this activation attempt.
        let currentness = ScriptedCurrentEbpfGraphRecoveryCurrentness::unavailable_on(2);

        assert!(matches!(
            runtime.activate_current_recovery_successor(
                ("up0", REPLACEMENT_IFINDEX),
                &pin_dir,
                DEFAULT_TC_PRIORITY,
                CurrentRecoverySuccessorRegistration::Pending,
                &currentness,
            ),
            Err(GtpuError::StateIndeterminate {
                operation: "fake_current_successor_activation"
            })
        ));

        let state = runtime.state();
        assert!(state.operations.contains(&"traffic_observation_enable"));
        assert!(state.operations.contains(&"traffic_observation_disable"));
        assert_eq!(
            state
                .operations
                .iter()
                .filter(|operation| **operation == "traffic_observation_reset")
                .count(),
            resets_before,
            "activation rollback must not rotate the retained gate generation"
        );
        assert_eq!(
            state.traffic_observation_gate[&REPLACEMENT_IFINDEX], disabled_gate,
            "revocation after the live cut restores the exact prior even generation"
        );
        assert!(state
            .successor_datapath_inert
            .contains(&REPLACEMENT_IFINDEX));
        assert!(state.successor_pending.contains(&REPLACEMENT_IFINDEX));
        drop(state);
        assert!(
            !runtime.dscp_datapath_usable(REPLACEMENT_IFINDEX)
                && !runtime.pdp_readback_datapath_usable(REPLACEMENT_IFINDEX),
            "a revoked activation with failed cleanup exposes neither tc traffic nor ordinary mutation"
        );
        assert_eq!(
            runtime
                .activate_current_recovery_successor(
                    ("up0", REPLACEMENT_IFINDEX),
                    &pin_dir,
                    DEFAULT_TC_PRIORITY,
                    CurrentRecoverySuccessorRegistration::Pending,
                    &TestCurrentEbpfGraphRecoveryCurrentness,
                )
                .expect("the exact retained pending generation retries"),
            CurrentRecoverySuccessorActivation::Activated
        );
        let state = runtime.state();
        assert_eq!(
            state.traffic_observation_gate[&REPLACEMENT_IFINDEX],
            disabled_gate + 1
        );
        assert!(!state.successor_pending.contains(&REPLACEMENT_IFINDEX));
        assert!(!state
            .successor_datapath_inert
            .contains(&REPLACEMENT_IFINDEX));
    }

    #[tokio::test]
    async fn activation_odd_gate_readback_failure_restores_exact_even_and_retry_converges() {
        let (_, runtime, _) = sealed_historical_25_successor().await;
        let pin_dir = PathBuf::from(DEFAULT_BPFFS_PIN_ROOT).join("up0");
        let disabled_gate = runtime.state().traffic_observation_gate[&REPLACEMENT_IFINDEX];
        let resets_before = runtime
            .state()
            .operations
            .iter()
            .filter(|operation| **operation == "traffic_observation_reset")
            .count();
        // This failure occurs after the fake odd gate transition, matching an
        // enable-map readback error rather than a pre-write refusal.
        runtime.fail_after_in_order(["traffic_observation_enable"]);

        assert!(matches!(
            runtime.activate_current_recovery_successor(
                ("up0", REPLACEMENT_IFINDEX),
                &pin_dir,
                DEFAULT_TC_PRIORITY,
                CurrentRecoverySuccessorRegistration::Pending,
                &TestCurrentEbpfGraphRecoveryCurrentness,
            ),
            Err(GtpuError::Io {
                operation: "traffic_observation_enable",
                ..
            })
        ));

        let state = runtime.state();
        assert!(state.operations.contains(&"traffic_observation_enable"));
        assert!(state.operations.contains(&"traffic_observation_disable"));
        assert_eq!(
            state
                .operations
                .iter()
                .filter(|operation| **operation == "traffic_observation_reset")
                .count(),
            resets_before,
            "an enable acknowledgement failure must not rotate the retry generation"
        );
        assert_eq!(
            state.traffic_observation_gate[&REPLACEMENT_IFINDEX],
            disabled_gate
        );
        assert!(state
            .successor_datapath_inert
            .contains(&REPLACEMENT_IFINDEX));
        assert!(state.successor_pending.contains(&REPLACEMENT_IFINDEX));
        assert!(state.traffic_observation_events.is_empty());
        assert!(state.traffic_observation_loss.is_empty());
        drop(state);
        assert!(
            !runtime.dscp_datapath_usable(REPLACEMENT_IFINDEX)
                && !runtime.pdp_cleanup_datapath_usable(REPLACEMENT_IFINDEX),
            "an indeterminate enable readback cannot activate traffic or map mutation"
        );
        assert_eq!(
            runtime
                .activate_current_recovery_successor(
                    ("up0", REPLACEMENT_IFINDEX),
                    &pin_dir,
                    DEFAULT_TC_PRIORITY,
                    CurrentRecoverySuccessorRegistration::Pending,
                    &TestCurrentEbpfGraphRecoveryCurrentness,
                )
                .expect("an acknowledgement failure preserves the exact retry generation"),
            CurrentRecoverySuccessorActivation::Activated
        );
    }

