    #[tokio::test]
    async fn current_successor_response_loss_retries_only_the_exact_finalized_receipt() {
        use crate::CurrentEbpfGraphRecoverySuccessorAdmissionOutcome as Admission;
        use crate::CurrentEbpfGraphRecoveryTerminalAdmissionOutcome as TerminalAdmission;

        let mut fake = FakeRuntime::new();
        fake.ifindexes
            .insert("s2bu-old".to_string(), REPLACEMENT_IFINDEX);
        let runtime = Arc::new(fake);
        let backend = EbpfGtpuDataplaneBackend::with_runtime(runtime.clone());
        let pin_dir = PathBuf::from(DEFAULT_BPFFS_PIN_ROOT).join("s2bu-old");
        runtime
            .state()
            .current_graphs
            .insert(pin_dir.clone(), FakeCurrentGraph::default());
        let intent = || {
            crate::CurrentEbpfGraphRecoveryIntent::new(
                "s2bu-old",
                crate::CurrentEbpfGraphWriterProof::previous_writer_stopped(),
            )
            .with_replacement_device(GtpDevice {
                name: "s2bu-old".to_string(),
                ifindex: REPLACEMENT_IFINDEX,
            })
            .with_drain_proof(crate::CurrentEbpfGraphDrainProof::sessions_and_traffic_drained())
        };
        let terminal = backend
            .recover_orphaned_current_ebpf_graph_with_authority_receipt(
                intent().into_request_with_authority(current_recovery_authority()),
            )
            .await
            .expect("publish current-source terminal");
        assert_eq!(
            backend
                .admit_current_ebpf_graph_terminal(
                    intent()
                        .into_terminal_admission_request(terminal, current_recovery_authority()),
                )
                .await
                .expect("broker admits current terminal"),
            TerminalAdmission::Admitted
        );
        let mut create = CreateGtpDeviceRequest::new("s2bu-old");
        create.bind_address = IpAddr::V4(Ipv4Addr::new(192, 0, 2, 1));
        backend.create_device(create).await.expect("seal successor");
        let target = || {
            let mut request = CreateGtpDeviceRequest::new("s2bu-old");
            request.bind_address = IpAddr::V4(Ipv4Addr::new(192, 0, 2, 1));
            crate::CurrentEbpfGraphRecoverySuccessorTarget::Legacy(request)
        };
        let receipt = match backend
            .inspect_current_ebpf_graph_successor(
                intent().into_successor_inspection_request(target(), current_recovery_authority()),
            )
            .await
            .expect("inspect sealed current successor")
        {
            crate::CurrentEbpfGraphRecoverySuccessorInspectionOutcome::Authenticated(receipt) => {
                receipt
            }
            outcome => panic!("unexpected successor inspection: {outcome:?}"),
        };
        assert_eq!(
            backend
                .admit_current_ebpf_graph_successor(intent().into_successor_admission_request(
                    target(),
                    receipt,
                    current_recovery_authority_for_successor_receipt(receipt),
                ),)
                .await
                .expect("admit exact current successor"),
            Admission::Admitted
        );
        assert!(runtime
            .state()
            .current_recovery_finalized_receipts
            .contains_key(&pin_dir));
        let active_gate_after_first_admission =
            runtime.state().successor_active_traffic_gate[&REPLACEMENT_IFINDEX];
        assert!(
            !runtime
                .state()
                .current_recovery_terminal_leaves
                .contains_key(&pin_dir),
            "the authority WAL was unlinked before the fresh-process retry"
        );
        assert!(
            !runtime
                .state()
                .current_recovery_successor_main_leaves
                .contains_key(&pin_dir),
            "the graph WAL was unlinked before the fresh-process retry"
        );
        let enables_after_first_admission = runtime
            .state()
            .operations
            .iter()
            .filter(|operation| **operation == "traffic_observation_enable")
            .count();
        assert_eq!(
            backend
                .admit_current_ebpf_graph_successor(intent().into_successor_admission_request(
                    target(),
                    receipt,
                    current_recovery_authority_for_successor_receipt(receipt),
                ))
                .await
                .expect("same-process response loss reauthenticates the finalized successor"),
            Admission::AlreadyFinalized
        );
        assert_eq!(
            runtime
                .state()
                .operations
                .iter()
                .filter(|operation| **operation == "traffic_observation_enable")
                .count(),
            enables_after_first_admission,
            "an exact already-active retry must not rewrite the live gate"
        );
        assert_eq!(
            runtime.state().successor_active_traffic_gate[&REPLACEMENT_IFINDEX],
            active_gate_after_first_admission,
            "the read-only retry retains the exact activated generation"
        );
        drop(backend);
        {
            let mut state = runtime.state();
            state.attached.remove(&REPLACEMENT_IFINDEX);
            state
                .successor_active_traffic_gate
                .remove(&REPLACEMENT_IFINDEX);
        }
        let restarted = EbpfGtpuDataplaneBackend::with_runtime(runtime.clone());
        let mut forged_bytes = receipt.encode();
        forged_bytes[232] ^= 1;
        let mut forged_digest = Sha256::new();
        forged_digest.update(b"opc.gtpu.current-ebpf-successor-receipt-codec\0r1");
        forged_digest
            .update(crate::CURRENT_EBPF_GRAPH_RECOVERY_SUCCESSOR_RECEIPT_CODEC_ID.as_bytes());
        forged_digest.update(&forged_bytes[..384]);
        forged_bytes[384..].copy_from_slice(&forged_digest.finalize());
        let forged = crate::CurrentEbpfGraphRecoverySuccessorReceipt::decode(forged_bytes)
            .expect("checksum-valid forged receipt is only typed input");
        assert_ne!(forged.commitment(), receipt.commitment());
        assert_eq!(
            restarted
                .admit_current_ebpf_graph_successor(intent().into_successor_admission_request(
                    target(),
                    forged,
                    current_recovery_authority_for_successor_receipt(forged),
                ))
                .await
                .expect("forged receipt is a bounded refusal"),
            Admission::Refused(CurrentEbpfGraphRecoveryRefusal::IndeterminateState)
        );
        assert!(matches!(
            restarted
                .admit_current_ebpf_graph_successor(intent().into_successor_admission_request(
                    target(),
                    receipt,
                    current_recovery_authority_for_successor_receipt(receipt),
                ),)
                .await,
            Err(GtpuError::RetryRequired {
                operation: "ebpf_current_successor_typed_create"
            })
        ));
        let mut recreate = CreateGtpDeviceRequest::new("s2bu-old");
        recreate.bind_address = IpAddr::V4(Ipv4Addr::new(192, 0, 2, 1));
        restarted
            .create_device(recreate)
            .await
            .expect("fresh process re-enters the exact ordinary typed create");
        assert!(!runtime
            .state()
            .successor_datapath_inert
            .contains(&REPLACEMENT_IFINDEX));
        drop(restarted);
        {
            let mut state = runtime.state();
            state.attached.remove(&REPLACEMENT_IFINDEX);
            state.uplink_filter_ready.remove(&REPLACEMENT_IFINDEX);
            state.downlink_filter_ready.remove(&REPLACEMENT_IFINDEX);
            state.uplink_filter_pin_dir.remove(&REPLACEMENT_IFINDEX);
            state.downlink_filter_pin_dir.remove(&REPLACEMENT_IFINDEX);
            state.pinned_config.remove(&pin_dir);
            state.schema.remove(&pin_dir);
            state
                .current_graphs
                .insert(pin_dir.clone(), FakeCurrentGraph::default());
        }
        let rollover = EbpfGtpuDataplaneBackend::with_runtime(runtime.clone());
        let terminal = rollover
            .recover_orphaned_current_ebpf_graph_with_authority_receipt(
                intent().into_request_with_authority(current_recovery_authority()),
            )
            .await
            .expect("publish the next current-source terminal");
        assert_eq!(
            rollover
                .admit_current_ebpf_graph_terminal(
                    intent()
                        .into_terminal_admission_request(terminal, current_recovery_authority()),
                )
                .await
                .expect("broker admits the next current terminal"),
            TerminalAdmission::Admitted
        );
        let mut second_create = CreateGtpDeviceRequest::new("s2bu-old");
        second_create.bind_address = IpAddr::V4(Ipv4Addr::new(192, 0, 2, 2));
        rollover
            .create_device(second_create)
            .await
            .expect("seal the next successor");
        let second_target = || {
            let mut request = CreateGtpDeviceRequest::new("s2bu-old");
            request.bind_address = IpAddr::V4(Ipv4Addr::new(192, 0, 2, 2));
            crate::CurrentEbpfGraphRecoverySuccessorTarget::Legacy(request)
        };
        let second_receipt =
            match rollover
                .inspect_current_ebpf_graph_successor(intent().into_successor_inspection_request(
                    second_target(),
                    current_recovery_authority(),
                ))
                .await
                .expect("inspect the next sealed successor")
            {
                crate::CurrentEbpfGraphRecoverySuccessorInspectionOutcome::Authenticated(
                    receipt,
                ) => receipt,
                outcome => panic!("unexpected next successor inspection: {outcome:?}"),
            };
        assert_ne!(receipt, second_receipt);
        assert_eq!(
            rollover
                .admit_current_ebpf_graph_successor(intent().into_successor_admission_request(
                    second_target(),
                    second_receipt,
                    current_recovery_authority_for_successor_receipt(second_receipt),
                ))
                .await
                .expect("rotate the finalized receipt for the next lifecycle"),
            Admission::Admitted
        );
        assert_eq!(
            rollover
                .admit_current_ebpf_graph_successor(intent().into_successor_admission_request(
                    target(),
                    receipt,
                    current_recovery_authority_for_successor_receipt(receipt),
                ))
                .await
                .expect("old receipt replay is a typed refusal after rollover"),
            Admission::Refused(CurrentEbpfGraphRecoveryRefusal::IndeterminateState)
        );
    }

    #[tokio::test]
    async fn grouped_successor_same_process_admission_uses_its_canonical_pin_namespace() {
        use crate::CurrentEbpfGraphRecoverySuccessorAdmissionOutcome as Admission;
        use crate::CurrentEbpfGraphRecoveryTerminalAdmissionOutcome as TerminalAdmission;

        let device_id = grouped_device_id(0x58);
        let endpoints = GtpuLocalEndpointSet::new(IpAddr::V6(ipv6_local()), None).unwrap();
        let runtime = Arc::new(FakeRuntime::new());
        let backend = EbpfGtpuDataplaneBackend::with_runtime(runtime.clone());
        let pin_dir = backend.grouped_pin_dir(device_id);
        let namespace = pin_dir
            .file_name()
            .and_then(std::ffi::OsStr::to_str)
            .expect("canonical grouped namespace")
            .to_string();
        runtime
            .state()
            .current_graphs
            .insert(pin_dir, FakeCurrentGraph::default());
        let intent = || {
            crate::CurrentEbpfGraphRecoveryIntent::new(
                &namespace,
                crate::CurrentEbpfGraphWriterProof::previous_writer_stopped(),
            )
            .with_replacement_device(GtpDevice {
                name: "s2bu-new".to_string(),
                ifindex: REPLACEMENT_IFINDEX,
            })
            .with_drain_proof(crate::CurrentEbpfGraphDrainProof::sessions_and_traffic_drained())
        };
        let target = || {
            crate::CurrentEbpfGraphRecoverySuccessorTarget::Grouped(grouped_device_request(
                "s2bu-new", device_id, endpoints,
            ))
        };
        let terminal = backend
            .recover_orphaned_current_ebpf_graph_with_authority_receipt(
                intent().into_request_with_authority(current_recovery_authority()),
            )
            .await
            .expect("publish grouped current terminal");
        assert_eq!(
            backend
                .admit_current_ebpf_graph_terminal(
                    intent()
                        .into_terminal_admission_request(terminal, current_recovery_authority()),
                )
                .await
                .expect("broker admits grouped terminal"),
            TerminalAdmission::Admitted
        );
        backend
            .create_device_with_endpoints(grouped_device_request("s2bu-new", device_id, endpoints))
            .await
            .expect("same process seals grouped successor");
        assert!(
            runtime
                .state()
                .successor_datapath_inert
                .contains(&REPLACEMENT_IFINDEX),
            "grouped linked hooks are packet-inert before broker admission"
        );

        // A shared ifindex, Linux name, or different grouped namespace must
        // not be mistaken for this pending successor.
        assert!(matches!(
            backend
                .create_device_with_endpoints(grouped_device_request(
                    "s2bu-new",
                    grouped_device_id(0x59),
                    endpoints,
                ))
                .await,
            Err(GtpuError::AlreadyExists)
        ));
        let wrong_endpoints =
            GtpuLocalEndpointSet::new(IpAddr::V6("2001:db8:10::99".parse().unwrap()), None)
                .unwrap();
        for wrong_target in [
            crate::CurrentEbpfGraphRecoverySuccessorTarget::Grouped(grouped_device_request(
                "s2bu-new",
                grouped_device_id(0x59),
                endpoints,
            )),
            crate::CurrentEbpfGraphRecoverySuccessorTarget::Grouped(grouped_device_request(
                "s2bu", device_id, endpoints,
            )),
            crate::CurrentEbpfGraphRecoverySuccessorTarget::Grouped(grouped_device_request(
                "s2bu-new",
                device_id,
                wrong_endpoints,
            )),
        ] {
            assert!(
                !matches!(
                    backend
                        .inspect_current_ebpf_graph_successor(
                            intent().into_successor_inspection_request(
                                wrong_target,
                                current_recovery_authority(),
                            ),
                        )
                        .await,
                    Ok(crate::CurrentEbpfGraphRecoverySuccessorInspectionOutcome::Authenticated(_))
                ),
                "a mismatched grouped target must not authenticate"
            );
        }

        let receipt = match backend
            .inspect_current_ebpf_graph_successor(
                intent().into_successor_inspection_request(target(), current_recovery_authority()),
            )
            .await
            .expect("inspect exact grouped successor")
        {
            crate::CurrentEbpfGraphRecoverySuccessorInspectionOutcome::Authenticated(receipt) => {
                receipt
            }
            outcome => panic!("unexpected grouped successor inspection: {outcome:?}"),
        };
        assert_eq!(
            backend
                .admit_current_ebpf_graph_successor(intent().into_successor_admission_request(
                    target(),
                    receipt,
                    current_recovery_authority_for_successor_receipt(receipt),
                ))
                .await
                .expect("admit exact same-process grouped successor"),
            Admission::Admitted
        );
        assert!(
            !runtime
                .state()
                .successor_datapath_inert
                .contains(&REPLACEMENT_IFINDEX),
            "grouped traffic activates only at exact broker admission"
        );
    }

    #[tokio::test]
    async fn current_recovery_resumes_partial_proof_under_terminal_predecessor_handoff() {
        for root_mode in [
            FakeHistorical25ControlRootMode::Predecessor0700,
            FakeHistorical25ControlRootMode::Predecessor0755,
            FakeHistorical25ControlRootMode::Predecessor0750,
        ] {
            let (backend, runtime) = backend_with_fake();
            let pin_dir = seed_historical_25(&runtime);
            {
                let mut state = runtime.state();
                state.historical_25_control_root_mode = root_mode;
                state
                    .historical_25_graphs
                    .get_mut(&pin_dir)
                    .expect("seeded historical graph")
                    .hooks_remaining = 0;
            }
            assert_eq!(
                backend
                    .recover_orphaned_historical_ebpf_graph(historical_25_recovery_request())
                    .await
                    .expect("retire exact historical graph"),
                crate::HistoricalEbpfGraphRecoveryOutcome::Removed,
                "terminal handoff for {root_mode:?}"
            );
            {
                let mut state = runtime.state();
                assert!(state.historical_25_root_handoff_published);
                assert_eq!(
                    state.historical_25_receipts[&pin_dir].phase,
                    FakeHistorical25ReceiptPhase::Terminal
                );
                state.current_graphs.insert(
                    pin_dir.clone(),
                    FakeCurrentGraph {
                        proof_committed: true,
                        pins_remaining: CURRENT_PIN_COUNT - 1,
                        ..FakeCurrentGraph::default()
                    },
                );
            }
            let request = CurrentEbpfGraphRecoveryRequest::new(
                "s2bu-historical",
                crate::CurrentEbpfGraphWriterProof::previous_writer_stopped(),
            )
            .with_replacement_device(GtpDevice {
                name: "s2bu".to_string(),
                ifindex: S2BU_IFINDEX,
            });
            assert_eq!(
                backend
                    .recover_orphaned_current_ebpf_graph_with_authority(
                        authorize_current_recovery_request(request),
                    )
                    .await
                    .expect("resume committed current proof"),
                CurrentEbpfGraphRecoveryOutcome::Removed,
                "current recovery retry under {root_mode:?}"
            );
            let state = runtime.state();
            assert!(!state.current_graphs.contains_key(&pin_dir));
            assert_eq!(
                state.historical_25_receipts[&pin_dir].phase,
                FakeHistorical25ReceiptPhase::Terminal
            );
            assert!(state.historical_25_operation_markers.contains(&pin_dir));
            assert_eq!(
                state.current_recovery_terminal_leaves[&pin_dir].source,
                crate::CurrentEbpfGraphRecoveryTerminalSource::CurrentGraph,
                "a real current graph remains current-source even under an inherited R5 root"
            );
        }
    }

