    #[tokio::test]
    async fn trusted_grouped_traffic_events_are_required_and_exactly_revocable() {
        let runtime = Arc::new(FakeRuntime::new());
        let device_id = grouped_device_id(0x61);
        let endpoints =
            GtpuLocalEndpointSet::new(IpAddr::V4(Ipv4Addr::new(192, 0, 2, 1)), None).unwrap();
        let backend = attach_grouped_fake(runtime.clone(), device_id, endpoints).await;
        let group = grouped_group(0x62, device_id, vec![grouped_v4_entry(0x1001, 0x2001)]);
        backend
            .reconcile_pdp_context_group(fresh_group_request(&backend, group.clone()))
            .await
            .unwrap();
        assert_eq!(
            backend.gtpu_traffic_proof_capability(),
            GtpuCapability::Available
        );
        let policy = opc_dataplane_observation::TrafficContinuityPolicy::new(
            2,
            std::time::Duration::from_millis(1),
            std::time::Duration::from_secs(2),
            std::time::Duration::from_secs(5),
            std::time::Duration::from_secs(2),
            8,
        )
        .unwrap();
        let superseded_authority =
            GtpuTrafficProofAuthority::new(group.clone(), 7, 9, 11, policy).unwrap();
        let mut superseded = begin_traffic_proof(&backend, &superseded_authority)
            .await
            .unwrap();
        let authority = GtpuTrafficProofAuthority::new(group.clone(), 12, 13, 14, policy).unwrap();
        let mut session = begin_traffic_proof(&backend, &authority).await.unwrap();
        assert!(matches!(
            backend
                .poll_gtpu_traffic_proof(&mut superseded)
                .await
                .unwrap(),
            GtpuTrafficProofPoll::Invalidated(GtpuTrafficProofInvalidation::AuthorityRevoked)
        ));
        backend.close_gtpu_traffic_proof(superseded).await.unwrap();
        assert!(matches!(
            backend.poll_gtpu_traffic_proof(&mut session).await.unwrap(),
            GtpuTrafficProofPoll::Pending
        ));
        let events = enqueue_public_request_and_private_return_traffic(&runtime, &group);
        runtime
            .state()
            .traffic_observation_events
            .insert(S2BU_IFINDEX, events);
        let proof = match backend.poll_gtpu_traffic_proof(&mut session).await.unwrap() {
            GtpuTrafficProofPoll::Proven(proof) => proof,
            other => panic!("test expected proof, got {other:?}"),
        };
        assert_eq!(
            validate_traffic_proof_with_authority(&backend, &proof, &authority)
                .await
                .unwrap(),
            GtpuTrafficProofValidation::Current
        );
        let store = registered_traffic_authority_store(&backend, &authority)
            .await
            .unwrap();
        let changed = GtpuTrafficProofAuthority::new(group.clone(), 13, 15, 15, policy).unwrap();
        store.replace(changed.clone()).await.unwrap();
        assert_eq!(
            validate_traffic_proof_with_authority(&backend, &proof, &changed)
                .await
                .unwrap(),
            GtpuTrafficProofValidation::Invalidated(
                GtpuTrafficProofInvalidation::ProductOwnerGenerationChanged
            )
        );
        assert_eq!(
            validate_traffic_proof_with_authority(&backend, &proof, &authority)
                .await
                .unwrap(),
            GtpuTrafficProofValidation::Invalidated(
                GtpuTrafficProofInvalidation::ProductOwnerGenerationChanged
            )
        );
        backend.close_gtpu_traffic_proof(session).await.unwrap();
        let authority = changed;

        let mut loss_session = begin_traffic_proof(&backend, &authority).await.unwrap();
        runtime
            .state()
            .traffic_observation_loss
            .insert(S2BU_IFINDEX, 1);
        assert!(matches!(
            backend
                .poll_gtpu_traffic_proof(&mut loss_session)
                .await
                .unwrap(),
            GtpuTrafficProofPoll::Invalidated(GtpuTrafficProofInvalidation::ContinuityLost)
        ));
        backend
            .close_gtpu_traffic_proof(loss_session)
            .await
            .unwrap();

        let mut generation_session = begin_traffic_proof(&backend, &authority).await.unwrap();
        {
            let mut state = runtime.state();
            let current = GtpuSessionGroupRecord::decode(
                &state.session_groups[&(S2BU_IFINDEX, group.id().to_bytes())],
            )
            .unwrap();
            let drifted =
                grouped_record_from_model(&group, current.generation().checked_next().unwrap())
                    .unwrap();
            state
                .session_groups
                .insert((S2BU_IFINDEX, group.id().to_bytes()), drifted.encode());
            state
                .session_uplink_index
                .retain(|(ifindex, _), _| *ifindex != S2BU_IFINDEX);
            state
                .session_downlink_index
                .retain(|(ifindex, _), _| *ifindex != S2BU_IFINDEX);
            for index in grouped_active_indexes(drifted).unwrap() {
                match index.key {
                    GroupedIndexKey::Uplink(key) => {
                        state
                            .session_uplink_index
                            .insert((S2BU_IFINDEX, key), index.value);
                    }
                    GroupedIndexKey::Downlink(key) => {
                        state
                            .session_downlink_index
                            .insert((S2BU_IFINDEX, key), index.value);
                    }
                }
            }
        }
        assert!(matches!(
            backend
                .poll_gtpu_traffic_proof(&mut generation_session)
                .await
                .unwrap(),
            GtpuTrafficProofPoll::Invalidated(
                GtpuTrafficProofInvalidation::DataplaneGenerationChanged
            )
        ));
        backend
            .close_gtpu_traffic_proof(generation_session)
            .await
            .unwrap();
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn canceled_poll_retains_the_affine_proof_and_authority_lease_for_retry() {
        let (backend, runtime, group, authority) = traffic_proof_fixture(0x5f).await;
        let mut session = begin_traffic_proof(&backend, &authority).await.unwrap();
        let store = registered_traffic_authority_store(&backend, &authority)
            .await
            .unwrap();
        let events = enqueue_public_request_and_private_return_traffic(&runtime, &group);
        runtime
            .state()
            .traffic_observation_events
            .insert(S2BU_IFINDEX, events);

        let (worker_entered, worker_release) = backend.pause_next_traffic_proof_worker_return();
        let entered_wait = tokio::task::spawn_blocking(move || {
            worker_entered.wait();
        });
        let mut poll = Box::pin(backend.poll_gtpu_traffic_proof(&mut session));
        tokio::select! {
            result = &mut poll => panic!("poll returned before its delivery-cancellation point: {result:?}"),
            result = entered_wait => result.unwrap(),
        }
        drop(poll);

        assert!(backend
            .traffic_attempts()
            .unwrap()
            .values()
            .any(|attempt| attempt.proof_issued && attempt.pending_proof.is_some()));
        let replacement_authority = authority.clone();
        let mut replacement =
            tokio::spawn(async move { store.replace(replacement_authority).await });
        assert!(
            tokio::time::timeout(std::time::Duration::from_millis(10), &mut replacement)
                .await
                .is_err()
        );

        worker_release.wait();
        assert!(matches!(
            replacement.await.unwrap(),
            Err(crate::GtpuTrafficProofAuthorityStoreUpdateError::AuthorityUnchanged)
        ));
        let proof = match backend.poll_gtpu_traffic_proof(&mut session).await.unwrap() {
            GtpuTrafficProofPoll::Proven(proof) => proof,
            other => panic!("retry expected the retained proof, got {other:?}"),
        };
        assert_eq!(
            validate_traffic_proof_with_authority(&backend, &proof, &authority)
                .await
                .unwrap(),
            GtpuTrafficProofValidation::Current
        );
        backend.close_gtpu_traffic_proof(session).await.unwrap();
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn queued_authority_replacement_cannot_deadlock_registration() {
        let (backend, _runtime, _group, authority) = traffic_proof_fixture(0x60).await;
        let store = registered_traffic_authority_store(&backend, &authority)
            .await
            .unwrap();
        let lease = store.lease().await;
        let replacement_authority = GtpuTrafficProofAuthority::new(
            authority.desired().clone(),
            authority.product_owner_generation().checked_add(1).unwrap(),
            authority.reconcile_fence().checked_add(1).unwrap(),
            authority.reconcile_revision().checked_add(1).unwrap(),
            authority.policy(),
        )
        .unwrap();
        let mut replacement = Box::pin(store.replace(replacement_authority));
        let mut context = Context::from_waker(std::task::Waker::noop());
        assert!(matches!(
            Future::poll(replacement.as_mut(), &mut context),
            Poll::Pending
        ));

        let registration = backend.register_gtpu_traffic_proof_authority(authority.clone());
        let result = tokio::time::timeout(std::time::Duration::from_secs(1), registration)
            .await
            .expect("registration must not wait behind the queued authority writer");
        assert!(matches!(
            result,
            Err(GtpuError::StateIndeterminate {
                operation: "ebpf_traffic_authority_store"
            })
        ));

        drop(lease);
        assert_eq!(replacement.await, Ok(()));
    }

